-- ===== 본문 재추출 반영 4/5 (parse800.py 생성) =====
-- 러닝헤더가 끼어든 본문/뒤바뀐 본문을 PDF에서 다시 추출한 값으로 교체. id·코스·진도는 그대로.
-- 이 파일 70행 / 전체 338행

UPDATE public.words SET meaning = '이연차액결제는 일정 기간중 지급결제시스템에 참가하는 기관의 양자간 또는 다자간에 지급할 총금액과 수취할 총금액을 모아서 상계 처리한 차액을 일정 시점 후에 결제하는 방식이다.', detailed_meaning = '이연차액결제는 일정 기간중 지급결제시스템에 참가하는 기관의 양자간 또는 다자간에 지급할 총금액과 수취할 총금액을 모아서 상계 처리한 차액을 일정 시점 후에 결제하는 방식이다. 금융기관의 순포지션은 해당 금융기관이 수취한 지급지시 금액의 합계에 서 송부한 지급지시 금액의 합계를 차감하여 산출한다. 이연차액결제방식은 상계한 차액만을 결제하면 되므로 결제유동성을 절감할 수 있는 장점이 있으나 결제시점까지 결제가 완료되지 않아 신용리스크에 노출되는 문제가 있다. 현재 우리나라의 소액결제시스템(어음교환, 타행환, 전자금융 등)은 이연차액결제 방식으로 최종 결제가 이루어지고 있다.', related_words = ARRAY['신용위험(신용리스크)']::text[] WHERE id = 444;  -- 이연차액결제
UPDATE public.words SET meaning = '국채·금융채·회사채 등의 채권은 이자지급 방법에 따라 할인채(Discount Bond), 이표채 (Coupon Bond), 복리채(Compound Interest Bond) 등으로 구분되는데', detailed_meaning = '국채·금융채·회사채 등의 채권은 이자지급 방법에 따라 할인채(Discount Bond), 이표채 (Coupon Bond), 복리채(Compound Interest Bond) 등으로 구분되는데 이표채는 채권의 권면에 이표(쿠폰, coupon)가 붙어 있어 이자지급일에 이를 떼어 제시함으로써 이자를 지급받는 채권을 말한다. 통상적으로 만기까지 일정 기간마다 이자를 지급하고 만기에는 원금을 지급하는 가장 일반적인 형태의 채권을 지칭한다. 이표채처럼 일정한 간격을 두고 주기적으로 수취하는 채권이자는 투자자의 입장에서 볼 때는 원래의 채권 투자자금 원본의 회수기간이 일부 앞당겨지는 효과를 얻게 된다. 이처럼 이표의 이자수취 만큼 투자자금 회수기간이 단축되는 효과를 감안하여 채권의 만기를 정밀하게 산출한 것을 듀레이션, 즉 평균만기라고 한다. 금리가 1% 변동할 때 채권의 가격은 듀레이션의 배율만큼 증폭되어 변동하기 때문에 유가증권투자에 있어서 매우 중요한 분석도구이다. 한편 이표채와 대비되는 개념으로 할인채와 복리채가 있다. 할인채는 이자의 지급 없이 만기에 원금을 지급하는 채권으로 액면보다 할인된 가격으로 발행되는데, 쿠폰 없이 발행되기 때문에 무이 표채 또는 제로쿠폰채(zero-coupon bond)라고 한다. 복리채는 이자를 중간에 지급하지않고 만기에 원금과 함께 일시에 지급하는 채권을 말한다.', related_words = '{}'::text[] WHERE id = 449;  -- 이표채
UPDATE public.words SET meaning = '일대일로는 아시아·아프리카·유럽을 잇는 중국의 대규모 경제권역 구상으로 2014년 11월중국 개최 아시아태평양경제협력체(APEC) 정상회의에서 당시 시진핑 총서기가 공식적으로 발표하였다.', detailed_meaning = '일대일로는 아시아·아프리카·유럽을 잇는 중국의 대규모 경제권역 구상으로 2014년 11월중국 개최 아시아태평양경제협력체(APEC) 정상회의에서 당시 시진핑 총서기가 공식적으로 발표하였다. 중국의 일대일로 구상은 일대(One Belt)와 일로(One Road)의 두 가지 핵심 무역경로를 제시하고 있다. 이중 ‘일로’는 과거 실크로드와 같은 개념으로 철도를 이용하여 중국 서부에서 유럽까지 연결하는 육상 무역경로를 의미한다. 다른 하나인 ‘일대’는 중국 연안에서 동남아시아, 아프리카, 유럽을 잇는 해상 기반의 무역벨트로 추진된다. 중국은 일대일로를 이용하여 중국의 수출기반을 더욱 다양하고 확고하게 구축해 나감으로 써 참여국들과 두터운 경제적 상호 협력관계를 조성한다는 목표를 일차적으로 내세우고 있다. 그리고 강화된 경제협력 네트워크를 기반으로 정치 및 문화분야까지 교류 촉진을 이끌어냄으로써 중국의 국제적 영향력을 한층 끌어올린다는 장기비전을 담고 있다. 그러나 중국의 글로벌 패권 장악에 대한 경계심과 함께 사업추진 방식과 관련하여 여러 문제점들이 드러나게 되면서 시행 초기의 활력이 점차 약화되는 상황이다. 특히 참여국의 인프라 건설자금이 원조형태가 아닌 빌려주는 차관형식으로 지원되면서 참여국들이 과도한 부채문제를 안게 되었으며 사업시행에 중국 기업과 중국인 노동자의 참여를 조건화함으로써 중국에 대한 의존도가 심화될 것이라는 등의 우려의 평가도 적지 않다.', related_words = '{}'::text[] WHERE id = 456;  -- 일대일로
UPDATE public.words SET meaning = '개발도상국의 수출 확대 및 공업화 촉진을 위하여, 선진국이 개발도상국으로부터 수입되는 농수산물, 공산품 및 반제품에 대하여는 아무런 조건 없이 “일반적”으로 무관세 또는 저율의 관세를 부과하는', detailed_meaning = '개발도상국의 수출 확대 및 공업화 촉진을 위하여, 선진국이 개발도상국으로부터 수입되는 농수산물, 공산품 및 반제품에 대하여는 아무런 조건 없이 “일반적”으로 무관세 또는 저율의 관세를 부과하는 관세 상의 특혜대우를 말한다. 여기서 “일반적”이란 의미는 영연방 특혜, 베네룩스 관세동맹 등 기존의 특혜관세제도와는 달리 지리적으로 여러 개 국가 에 국한되지 않고 범세계적으로 적용된다는 것을 뜻한다. 현재 일반특혜관세를 공여하는 국가로는 미국, 일본, 캐나다, 호주, 뉴질랜드, EC 등이 있다. 이들 특혜공여국은 특혜 대상품목, 특혜 폭, 원산지 기준 등을 정하고 이러한 제반요건을 충족한 경우에 한하여 특혜관세를 적용하고 있다.', related_words = ARRAY['상계관세','할당관세제도']::text[] WHERE id = 458;  -- 일반특혜관세
UPDATE public.words SET meaning = '일중당좌대출제도는 한은금융망의 자금결제가 원활히 이루어지도록 은행 참가기관에 대하여 영업시간 중 일시적인 결제부족자금을 실시간으로 지원하는 제도로 2000년 9월 도 입되었다.', detailed_meaning = '일중당좌대출제도는 한은금융망의 자금결제가 원활히 이루어지도록 은행 참가기관에 대하여 영업시간 중 일시적인 결제부족자금을 실시간으로 지원하는 제도로 2000년 9월 도 입되었다. 일중당좌대출은 한국은행에 개설된 참가은행의 당좌예금계좌 잔액을 초과한 지급 또는 결제의 요청이 있는 경우 가용담보 범위 내에서 자동으로 실행되는 방식으로 운용된다. 은행별 일중당좌대출의 한도는 없으나 참가기관의 일중당좌대출에 대한 과도 한 의존을 방지하기 위하여 자유한도(금융기관 자기자본의 25%)를 초과하는 대출금에 대해 이자를 부과하고 있다. 한편 은행이 당일 중 상환마감시각까지 일중당좌대출금을 상환하지 못하는 경우에는 한국은행의 익일물 자금조정대출로 전환하여 지원하고 있다. 한 편 한은금융망에 참가하는 비은행금융기관에 대한 일중유동성 지원은 일중RP를 통해이루어진다.', related_words = ARRAY['거액지급시스템','결제리스크','일중RP제도']::text[] WHERE id = 460;  -- 일중당좌대출제도
UPDATE public.words SET meaning = 'CMS(Cash Management Service)공동망은 금융기관을 통해 대량의 출금 및 입금서비스를 제공하는 지급시스템으로 금융결제원이 1996년 8월부터 가동하였다.', detailed_meaning = 'CMS(Cash Management Service)공동망은 금융기관을 통해 대량의 출금 및 입금서비스를 제공하는 지급시스템으로 금융결제원이 1996년 8월부터 가동하였다. 먼저 출금이 체 서비스는 각종 상품 판매대금, 서비스 이용대금, 수업료, 회비 등을 받는 자가 다수의 납부자 예금계좌나 예탁금계좌에서 출금하여 입금받는 업무로서 지로 자동이체와 유사하다. 입금이체 서비스는 각종 상품 구입대금, 배당금, 연금, 급여 등을 보내는 자가 계좌에 서 자금을 인출하여 타 금융기관의 수취인 계좌로 자금을 지급하는 업무로서 지로의 대량지급과 비슷하다. CMS는 각종 사회단체, 학교 및 학원 등을 중심으로 활발히 이용되고 있으며 이를 통해 비교적 저렴한 비용으로 매번 금융기관을 방문하거나 인터넷뱅킹 등을 통해 이체하지 않고 정기적인 대금 수납 및 지급을 처리할 수 있다.', related_words = ARRAY['입금이체','출금이체']::text[] WHERE id = 462;  -- 자금관리서비스(CMS)공동망
UPDATE public.words SET meaning = '경제정책을 입안하고 시행하는 과정은 간단하지 않다.', detailed_meaning = '경제정책을 입안하고 시행하는 과정은 간단하지 않다. 정책의 효율성을 점검해야 하며, 효율성이 입증되었다고 해도 경기상황에 대한 정보수집과 예측, 정책입안, 입법절차 등 을 거쳐 실제로 정책을 시행하기까지 많은 시간이 소요된다. 또한 정책시행에 있어서도준칙을 따를 것인가 재량에 의존할 것인가도 정책의 효과에 영향을 미친다. 이와 같이 적극적인 경제정책은 여러 가지 한계와 어려움 때문에 상황에 따라서는 더 큰 부작용이 발생할 가능성이 내재되어 있다. 이러한 점을 고려하여 일부 경제학자들은 수동적인 자동안정화장치를 경제정책으로 활용할 것을 권장하였다. 자동안정화장치의 대표적인 예로는 누진세를 꼽을 수 있다. 누진 세제는 경기가 침체할 때 추가적인 입법 과정 없이 자동으로 조세부담을 줄여 경기를 활성화하는 효과가 있다. 반대로 경기가 과열일 때는 과세표준이 늘어나 조세부담이 커지면서 경기를 진정시킬 수 있다. 사회보장제도나 실업보험제도 등 도 자동안정화장치의 예이다. 자동안정화장치는 이처럼 경기변동의 폭을 자동으로 완화해 주는 장점을 갖고 있지만, 경기가 회복되기 시작하여 완전고용 상태로 가는 과정을 더디게 하는 단점도 있다. 경기가 회복되면서 소득세가 늘어나 소비지출이 줄고 실업수당의 지급이 줄어들면서 정부지출이 감소하여 총수요의 증가가 일부 상쇄되기 때문이다.', related_words = ARRAY['경기조절정책/경제안정화정책','사회보험']::text[] WHERE id = 467;  -- 자동안정화장치
UPDATE public.words SET meaning = '자발적 실업이란 일할 의사가 있어 고용되기를 원하지만 현재의 임금수준이 낮다고 생각하여 스스로 일하고 있지 않는 상태에 있는 실업이다.', detailed_meaning = '자발적 실업이란 일할 의사가 있어 고용되기를 원하지만 현재의 임금수준이 낮다고 생각하여 스스로 일하고 있지 않는 상태에 있는 실업이다. 자발적 실업은 완전고용과 밀접한 관계가 있다. 완전고용은 경제활동인구 가운데 현재의 주어진 임금수준에서 일할 의사가 있는 사람은 모두 고용되는 상태이다. 즉, 완전고용의 상황에서는 비자발적 실업은 전혀존재하지 않는다. 따라서 자발적 실업이란 완전고용을 가정할 때 경제활동인구에서 고용된 인구를 뺀 나머지를 자발적 실업이라 할 수 있다. 다만 완전고용 상태에서도 모두 고용될 수 없는 불가피한 두 가지의 실업이 있다. 첫째, 현재의 일자리보다 더 나은 일자리를 모색하는 과정에서 나타나는 마찰적 실업이다. 둘째, 특정 산업의 사양화나 최저임금제, 노동조합, 임금경직성 등 제도적 요인 때문에 발생하는 구조적 실업이다. 이러한 두 실업은 경기가 호황이든 불황이든 상관없이 발생하므로 완전고용을 정의할 때는 제외한다.', related_words = ARRAY['마찰적 실업','실망실업자']::text[] WHERE id = 468;  -- 자발적 실업
UPDATE public.words SET meaning = '자본거래의 자유화란 직접투자나 간접투자를 불문하고 정부 혹은 민간이 제3국과의 사이 에 자본을 사용 목적, 방법 등에 대해 어떠한 간섭도 받지 않은 채 자유롭게 공급 또는 도 입하고 나아가 동', detailed_meaning = '자본거래의 자유화란 직접투자나 간접투자를 불문하고 정부 혹은 민간이 제3국과의 사이 에 자본을 사용 목적, 방법 등에 대해 어떠한 간섭도 받지 않은 채 자유롭게 공급 또는 도 입하고 나아가 동 자본의 원금과 이자의 상환 등에 제한을 받지 않도록 하는 것, 간단히말해 국경 간의 자본이동을 자유화하는 것을 의미한다. 따라서, 자본거래의 자유화는 내국인 또는 국내기업(거주자)의 국외 투자와 외국인 또는 외국기업(비거주자)의 대내 투자양 측면의 자유화를 포괄한다. 자본거래의 자유화는 무역자유화 및 외환거래 자유화와 함 께 일국 경제체제의 개방 및 자유화를 달성하는 가장 중요한 요소이며 최종단계이기도 하다. 우리나라는 1980년대부터 자본거래의 자유화를 추진하기 시작하여 1992년 주식시장을 부분적으로 개방하였고 1996년 OECD 가입과 1997년 외환위기를 계기로 그 속도를 높였다. 특히 외환위기 이후 외국자본의 유치 필요성이 높아지면서 주식, 채권 및 단기금융시장이 순차적으로 개방되었고 1999년 외국환거래법 시행과 함께 국내기업 및 금융기관뿐만 아니라 개인의 외환 및 자본거래도 대폭 자유화하였으며, 2006년 외화거래 자유화를 추진하여 거주자의 해외부동산 투자 자유화, 대외채권회수의무 면제 등 자본거래를 더욱 자유화하였다.', related_words = ARRAY['외국환거래법','경제협력개발기구(OECD)']::text[] WHERE id = 469;  -- 자본거래자유화
UPDATE public.words SET meaning = '금융기관이 보유자산 등에 대해 건전성 여부를 분석하여 불건전자산의 발생을 예방하고 이미 발생한 불건전자산에 대하여는 조기 정상화를 촉진하게 함으로써 금융기관의 자산운용 건전화를 도모하는 한편', detailed_meaning = '금융기관이 보유자산 등에 대해 건전성 여부를 분석하여 불건전자산의 발생을 예방하고 이미 발생한 불건전자산에 대하여는 조기 정상화를 촉진하게 함으로써 금융기관의 자산운용 건전화를 도모하는 한편 영업활동에서 발생하는 손실 중 사전에 예상되는 손실에 대한 손실흡수력을 확보하고 있다. 금융기관은 감독당국의 자산건전성 분류기준에 따라 보유자산의 건전성 상태를 매 분기 정기적으로 점검하여 정상, 요주의, 고정, 회수의문, 추정손실의 5단계로 분류하고 이에 상응하는 적정 수준의 대손충당금 등을 적립·유지하여야 한다.', related_words = ARRAY['대손충당금적립비율']::text[] WHERE id = 474;  -- 자산건전성 분류
UPDATE public.words SET meaning = '일반적으로 특수목적기구(SPV)가 자산보유자로부터 자산을 양도·신탁 받아 이를 기초로 자산유동화증권(ABS)을 발행하고 해당 유동화자산의 관리·운용·처분에 의한 수익이 나 차입금으로', detailed_meaning = '일반적으로 특수목적기구(SPV)가 자산보유자로부터 자산을 양도·신탁 받아 이를 기초로 자산유동화증권(ABS)을 발행하고 해당 유동화자산의 관리·운용·처분에 의한 수익이 나 차입금으로 자산유동화증권의 원리금 또는 배당금을 지급하는 일련의 행위를 말한다. 자산유동화(Securitization)는 자산보유자의 신용과 분리하여 유동화자산 그 자체에서 발생되는 현금흐름을 바탕으로 자금을 조달하는 금융기법으로서 자산보유자의 재무구조개선, 자금조달 비용 절감, 투자자 확대 등의 장점이 있다. 자산유동화증권은 유동화대상자산에 따라 그 종류가 다양한데 예를 들어 기초자산이 주택담보대출인 경우에는 주택저당증권(MBS), 기초자산이 기업 매출채권인 경우에는 자산담보부 기업어음(ABCP)이라고 한다. 「자산유동화에 관한 법률」에 의한 자산유동화증권 발행기관(SPV)으로는 유동화전문회사, 자산유동화업무를 전업으로 하는 외국법인, 「자본시장과 금융투자업에 관한 법률」상 신탁업자 등이 있다.', related_words = ARRAY['특수목적기구(SPV)','주택저당증권(MBS)']::text[] WHERE id = 475;  -- 자산유동화
UPDATE public.words SET meaning = '석유, 가스, 광물 등 천연자원을 보유한 국가가 이에 대한 소유권과 관리권을 강화하고 이 를 지렛대 삼아 국제사회에 대한 경제적, 정치적 영향력을 확대하는 국가주의적 경향을 자원민족주의라 일컫는다.', detailed_meaning = '석유, 가스, 광물 등 천연자원을 보유한 국가가 이에 대한 소유권과 관리권을 강화하고 이 를 지렛대 삼아 국제사회에 대한 경제적, 정치적 영향력을 확대하는 국가주의적 경향을 자원민족주의라 일컫는다. 자원에 대한 소유권과 관리권을 강화하기 위해 외국기업이 소유하고 있는 자원을 국유화하거나 외국기업의 자국내 자원개발에 대해 조건을 까다롭게하고 국내 자원의 수출량을 제한하는 등의 방식이 대표적인 자원민족주의 행태이다. 자원민족주의는 자국의 국가안보와 이익보호라는 측면에서 과거로부터 계속되고 있는 일종의 이데올로기적 이념주의 한 유형이지만 최근 들어 더욱 강화되는 모습을 보이고 있다. 특히 코로나 위기를 계기로 자원에 대한 안정적 공급망 확보가 중요해진 이후에는 이를 둘러싼 미국과 중국간 경쟁적 갈등이 심화되면서 자원민족주의 경향이 우려 수준에 이르고 있는데 배터리 등 디지털산업 발전에 필수적인 희토류를 대량으로 보유하고 있는 중국 및중남미 국가들의 강력한 생산 및 수출 통제가 대표적 사례이다.', related_words = '{}'::text[] WHERE id = 478;  -- 자원민족주의
UPDATE public.words SET meaning = '작업증명(Proof-of-Work)은 제3자로부터의 서비스 요청(request)이 악의적인 공격 (spam 또는 DoS, Denial of Service)이 아님을 증명하기 위해서, 자원이', detailed_meaning = '작업증명(Proof-of-Work)은 제3자로부터의 서비스 요청(request)이 악의적인 공격 (spam 또는 DoS, Denial of Service)이 아님을 증명하기 위해서, 자원이 소모되는 작업을 추가로 수행할 것을 요구하는 것을 의미한다. 대표적인 작업증명으로는 웹사이트 로 그인시 특정한 문자 및 그림을 읽고 입력할 것을 요구하는 캡차를 들 수 있다. 작업증명의 특징은 비대칭성인데, 서비스 요청자가 수행하는 데는 어느 정도 자원이 소모되지만 이를 확인하기는 매우 쉬워야 한다. 작업증명은 가상자산인 비트코인 등을 채굴하는 합의 과정에 활용되고 있다.', related_words = ARRAY['비트코인']::text[] WHERE id = 481;  -- 작업증명
UPDATE public.words SET meaning = '잠재GDP성장률은 노동이나 자본 등의 자원을 최대로 활용하였을 때 유지되는 실질GDP 의 증가율로서 한 나라 경제의 최대성장능력을 의미한다.', detailed_meaning = '잠재GDP성장률은 노동이나 자본 등의 자원을 최대로 활용하였을 때 유지되는 실질GDP 의 증가율로서 한 나라 경제의 최대성장능력을 의미한다. 잠재GDP는 일정한 잣대로 추계할 수 없는 추상적인 개념이어서, 추정에 사용되는 원칙이나 통계분석기법 등에 따라 결과가 상이하다는 한계가 있다. 한편 잠재GDP는 성장률도 의미가 있지만 그 수준이 실제GDP보다 얼마나 높은가 또는 낮은가를 살피는 것도 매우 중요하다. 실제GDP 성장률이 잠재GDP성장률을 상회하더라도 그 수준은 잠재GDP를 하회할 수도 있다. 또한 우리나라와 같이 대외의존도가 매우 높은 경우에는 정의에 의한 생산요소의 완전고 용으로 규정하기에는 어려움이 있다. 그럼에도 잠재GDP성장률은 경제의 적정성장목표를 설정하는 데 유용하여 거시경제정책을 수립하고 시행하는 데 있어 널리 활용되고 있다.', related_words = ARRAY['GDP갭']::text[] WHERE id = 482;  -- 잠재GDP성장률
UPDATE public.words SET meaning = '금융시장은 거래 금융상품의 만기를 기준으로 단기금융시장(Money Market)과 자본시장(Capital Market)으로 구분되는데 자본시장은 만기 1년 이상의 장기채권이나 만기가 없는 주식이', detailed_meaning = '금융시장은 거래 금융상품의 만기를 기준으로 단기금융시장(Money Market)과 자본시장(Capital Market)으로 구분되는데 자본시장은 만기 1년 이상의 장기채권이나 만기가 없는 주식이 거래되는 시장을 말한다. 자본시장은 주로 기업, 정부 등 자금 부족부문이 자금잉여부문으로부터 장기적으로 필요한 자금을 조달하는 데 활용되고 있어 장기금융시장이 라고 부른다. 우리나라의 자본시장에는 주식이 거래되는 주식시장과 국채, 회사채 및 금융채 등이 거래되는 채권시장이 있다.', related_words = ARRAY['단기금융시장']::text[] WHERE id = 484;  -- 장기금융시장(자본시장)
UPDATE public.words SET meaning = '장기침체(Secular Stagnation)는 1938년 Hansen이 기술 정체와 인구증가율 둔화에 따른 투자기회의 대폭 축소로 미국경제가 1930년대 대공황 발생 이후에도 회복되지 못하고 과소', detailed_meaning = '장기침체(Secular Stagnation)는 1938년 Hansen이 기술 정체와 인구증가율 둔화에 따른 투자기회의 대폭 축소로 미국경제가 1930년대 대공황 발생 이후에도 회복되지 못하고 과소 투자 및 총수요 부족에 직면할 것으로 예측하면서 처음 사용한 용어로 알려져 있으며, 최근에는 하버드대학의 Summers 교수가 IMF경제포럼(2013.11) 연설에서 “선진국 경제는 2000년대 초부터 구조적 요인에 의해 장기침체에 진입하였다”고 주장하면서 널리 회자되고 있다. 장기침체란 경제활동의 장기적 침체라는 뜻으로 대체로 실제GDP가 잠재GDP를 하회하는 가운데 총수요가 억제 되어 있거나 공급측면에서 잠재GDP가 정체되어 있는 상황으로 정의된다. 여기서 장기는 인구고령화 등에 따른 노동증가율 감소, 혁 신 정체, 자본투자 감소 등 공급요인에 의해 성장잠재력이 축소되는 현상과 연관이 있다. 그리고 침체는 디레버리징 등 기초경제여건의 변화, 소득불평등 심화, 재정지출 축소, 글로벌 금융위기 이후 위험회피성향의 증가 등 수요요인에 의해 성장회복이 지연되거나 성장이 정체되는 것으로 경기순환과 관련이 있다. 장기침체란 용어 자체가 수요요인(경기순환)과 공급요인(성장잠재력)이 혼재되어 있기 때문에 장기침체 여부와 그 원인에 대해서 는 다양한 시각이 존재한다.', related_words = ARRAY['경기조절정책/경제안정화정책','골디락스경제','대안정기']::text[] WHERE id = 485;  -- 장기침체
UPDATE public.words SET meaning = '장단기금리차란 일정 시점에서 장기금리와 단기금리의 차이를 의미한다.', detailed_meaning = '장단기금리차란 일정 시점에서 장기금리와 단기금리의 차이를 의미한다. 장단기금리차는 다양한 만기의 지표금리를 이용해서 산출할 수 있다. 예를 들어 어떤 시점에서 국고 채금리(3년 만기)가 2.0%이고 한국은행 정책금리가 1.5%라면 여기서 장단기금리차는 0.5%p(2.0%-1.5%)이다. 또는 10년만기 국고채금리와 3년만기 국고채금리의 차이도 또하나의 장단기금리차로 이해할 수 있다. 여기서의 장단기는 통상 1년을 기준으로 하기 보다는 비교하려는 만기의 상대성에 달려있다. 즉 후자의 예에서 10년을 장기로 보는 경우 3년은 단기의 의미로 비교된 것이다. 장단기금리차는 시장이 경제를 어떻게 바라보고 있는지를 판단하는데 유용한 지표로 활용된다. 장단기금리차가 줄어들고 있다면(정책금리는 한국은행이 결정하기 때문에 새로운 정책금리 결정이 나오기 전까지는 변함이 없는 반면 장기금리는 하락) 이는 경제성장률이 떨어지고 실업률이 상승하는 등 향후 경제가 더나빠질 것으로 시장이 기대한다고 볼 수 있다. 특히 이런 상황에서 경기진작을 위해 한국은행이 정책금리를 인하할 것이라는 기대가 강화되는 경우에는 이런 현상이 더욱 두드러진다. 시장이 정책금리 인하를 극단적으로 기대하는 경우에는 3년 국고채금리가 한국은 행 정책금리를 하회하는 현상도 발생한다. 이를 장단기금리 역전이라고 한다. 반대로 장 ㅈ단기금리차가 확대되고 있다면 향후 경제가 좋아질 것이라고 시장이 기대한다고 볼 수 있다. 특히 경제성장률이 잠재성장률에 근접하고 있어 한국은행이 정책금리를 인상할 것이 라는 기대가 형성되는 경우 그 차이는 더욱 확대된다. 또한 장단기금리차는 채권의 수급에 의해서도 영향을 받는다. 장기채권에 대한 수요가 많아지면 장기금리가 하락하여 장단기금리차가 축소되고 장기채권의 공급이 많아지면 장기금리가 상승하여 장단기금리차가 확대된다. 장단기금리차의 변화는 수익률곡선의 형태가 가팔라지거나(steepening) 평탄해지는(flattening) 것으로 표현되기도 한다. 수익률곡선이 가팔라진다는 것은 장단기금리차가 확대되는 것을 의미하고 수익률곡선이 평탄해진다는 것은 장단기금리차가 축소되는 것을 의미한다.', related_words = ARRAY['기준금리']::text[] WHERE id = 487;  -- 장단기금리차
UPDATE public.words SET meaning = '국민계정에서 재산소득(Property Income)이란 금융자산 또는 자연자원(주로 토지 및 지하자원)의 소유주가 타 경제주체에게 자금을 공급하거나 유형 비생산자산을 사용하도록하고 그 대가로서', detailed_meaning = '국민계정에서 재산소득(Property Income)이란 금융자산 또는 자연자원(주로 토지 및 지하자원)의 소유주가 타 경제주체에게 자금을 공급하거나 유형 비생산자산을 사용하도록하고 그 대가로서 수취하는 소득을 말한다. 금융자산은 이자, 배당 등 투자소득의 형태로, 자연자원은 임료의 형태로 재산소득이 발생한다. 이를 구체적으로 살펴보면, 재산소득은 이자, 배당 및 준법인기업소득인출, 국외직접투자에 대한 재투자수익, 투자소득지급, 임 료 등으로 분류된다. 이자는 예금, 채무증권, 대출 및 기타 수취권 등 금융자산의 소유주가 위에 자금을 공급하거나 유형 비생산자산을 사용하도록 하고 그 대가로서 수취하는 소득을 말한다. 배당은 주주가 법인기업으로부터 자금 공여의 대가로 취득하게 되는 소득이 다. 준법인기업소득인출은 소유주가 기업에 자금을 투자함으로써 발생하는 소유주의 소득이다. 국외직접투자에 대한 재투자수익은 거주자의 해외직접투자 또는 비거주자의 국내직접투자에서 발생한 이익이 배당 등의 형태로 실제로 배분되고 남은 유보이익을 의제하여 투자자에게 지급 처리한 것을 말한다. 투자소득지급은 보험가입자의 법적준비금 및연금자산 등의 운용에서 수취하는 투자소득을 해당 자산의 실제 소유자에게 지급된 것으로 의제처리 한 소득이다. 임료는 토지, 지하자원 등 자연자원 사용에 대한 재산소득으로, 현재 우리나라는 토지에 대한 임료만을 계상하고 있다.', related_words = ARRAY['본원소득']::text[] WHERE id = 489;  -- 재산소득
UPDATE public.words SET meaning = '자국 통화와 다른 외국 통화가 국내외환시장에서 직접적으로 거래되지 않는 경우 각각의 시장에서 결정되는 가격을 이용해 산출하는 환율을 말한다.', detailed_meaning = '자국 통화와 다른 외국 통화가 국내외환시장에서 직접적으로 거래되지 않는 경우 각각의 시장에서 결정되는 가격을 이용해 산출하는 환율을 말한다. 예를 들면 일본 엔화와 원화를 교환할 수 있는 시장이 없으므로 원/엔 환율은 서울 외환시장에서 결정된 원/달러 환율과 도쿄 외환시장에서 형성된 엔/달러 환율을 이용하여 산출한다. 만약 원/달러 환율이 1,100원이고, 엔/달러 환율이 달러당 110엔이라면 재정환율인 원/엔 환율은 100엔당 1,000원이 된다. 이처럼 재정환율을 사용하는 이유는 세계적으로 각국 외환시장에서의 거래가 대부분 미 달러화를 중심으로 이루어지고 있어 기타 통화 간 외환시장은 발달되어있지 않기 때문이다. 2025년 6월 현재 우리나라는 서울외국환중개회사가 서울 외환시장에서 결정되는 원/달러, 원/위안 환율과 국제금융시장에서 형성된 미 달러화와 다른 통화간 환율(크로스 레이트)을 매개로 하여 55개 통화에 대한 재정환율을 매일 고시하고 있다.', related_words = ARRAY['기준환율']::text[] WHERE id = 492;  -- 재정환율
UPDATE public.words SET meaning = '금융업무에 컴퓨터 및 정보통신기술을 적용하여 자동화 및 전자화(Network 화)를 구현하는 것을 말한다.', detailed_meaning = '금융업무에 컴퓨터 및 정보통신기술을 적용하여 자동화 및 전자화(Network 화)를 구현하는 것을 말한다. 국내의 전자금융거래법에서는 이러한 전자금융거래를 ‘금융회사또는 전자금융업자가 전자적 장치를 통하여 금융상품 및 서비스를 제공하고, 이용자가 금융회사 또는 전자금융업자의 종사자와 직접 대면하거나 의사소통을 하지 아니하고 자동화된 방식으로 서비스를 이용하는 거래’로 정의하고 있다. 전자금융의 수단으로는 홈뱅킹, 펌뱅킹 등의 PC뱅킹과 전화기를 이용한 폰뱅킹이 주로 이용되었으나, 정보처리 기술및 통신기술을 활용한 각종 전자금융서비스의 개발이 이루어짐으로써 시간적·공간적 제약 없이 금융서비스를 이용할 수 있게 되었다. 최근에는 스마트폰의 등장과 함께 다양한 직불 및 선불 전자지급수단이 출시되고 금융기관을 중심으로 모바일금융서비스 제공이 확산되고 있다. 특히 금융과 IT기술의 융합이 가속화되면서 출현한 금융서비스는 기존 금융기관이 아닌 IT업체들의 전자금융산업 참여를 가능하게 하였으며, 금융과 기술의 융합인 핀테크(Fintech)가 등장하는 등 관련 산업환경이 변화하면서 비금융기업들의 참여가 더욱 활발하게 진행될 것으로 예상된다.', related_words = ARRAY['금융EDI','핀테크']::text[] WHERE id = 497;  -- 전자금융
UPDATE public.words SET meaning = '금융기관 수납장표의 전자정보교환제도(Truncation)란 공과금 납부용지, 지로용지, 어음, 수표 등 금융기관에서 수납하는 각종 장표를 표준화하고 전산화하여 장표 실물의 이 동 없이 전산망을', detailed_meaning = '금융기관 수납장표의 전자정보교환제도(Truncation)란 공과금 납부용지, 지로용지, 어음, 수표 등 금융기관에서 수납하는 각종 장표를 표준화하고 전산화하여 장표 실물의 이 동 없이 전산망을 통한 정보(전산데이터)의 이동만으로 교환 업무를 처리하는 제도이다. 이를 통해 장표의 실물 이동 및 수작업에 따른 인적·물적 비용, 분실, 도난 등 사고 발생및 오류발생 가능성을 크게 감소시키게 되었다. 수납장표 전자정보교환제도는 2000년 5 월 자기앞수표를 시작으로 대상 장표의 범위를 확대하여 2009~2010년중 어음 및 기타수표의 교환이 정보화되면서 마무리되었다. 이에 따라 현재 금융결제원은 어음, 수표 및장표지로의 교환업무를 모두 전자정보교환방식으로 수행하고 있다.', related_words = ARRAY['어음교환','전자어음']::text[] WHERE id = 503;  -- 전자정보교환제도
UPDATE public.words SET meaning = '전자지급결제대행(PG; Payment Gateway)이란 인터넷 쇼핑몰 등의 전자상거래에서 구매자로부터 대금을 수취하여 판매자에게 지급될 수 있도록 지급정보를 송·수신하는 것 또는 그 대가의', detailed_meaning = '전자지급결제대행(PG; Payment Gateway)이란 인터넷 쇼핑몰 등의 전자상거래에서 구매자로부터 대금을 수취하여 판매자에게 지급될 수 있도록 지급정보를 송·수신하는 것 또는 그 대가의 정산을 대행하거나 매개하는 것을 의미한다. 가령 구매자가 인터넷 쇼핑몰에 서 신용카드로 대금을 지급하는 경우 신용카드 PG업자는 해당 쇼핑몰(가맹점)을 대신하여신용카드사에 거래내역 및 승인정보 등 지급정보를 전송하고 신용카드사로부터 대금을 지급받아 일정 수수료를 공제한 후 가맹점에 지급하게 된다. 온라인상의 전자상거래 규모가 급속히 늘어남에 따라 PG업자는 IT업체가 중심이 되어 동 서비스를 제공하고 있다.', related_words = ARRAY['지급결제시스템']::text[] WHERE id = 504;  -- 전자지급결제대행(PG)
UPDATE public.words SET meaning = 'IC카드 등에 화폐가치를 저장하였다가 상품 등의 구매에 사용할 수 있는 전자지급수단으로서 범용성과 환금성을 갖춘 것을 말한다.', detailed_meaning = 'IC카드 등에 화폐가치를 저장하였다가 상품 등의 구매에 사용할 수 있는 전자지급수단으로서 범용성과 환금성을 갖춘 것을 말한다. 전자화폐(Electronic Money)의 유형은 가치저장 매체에 따라 IC카드형과 네트워크형으로 구분할 수 있다. IC카드형은 플라스틱 카드 위에 부착된 IC칩에 화폐가치를 저장하였다가 상품이나 서비스를 구매한 후 가맹점용단말기 등을 통하여 대금을 지급하는 형태의 전자화폐로 국내에는 K-Cash, VisaCash, MYbi 등이 있다. 인터넷 네트워크를 통하여 구매대금을 지급하는 형태의 네트워크형 전자화폐는 현재는 발행되지 않고 있다.', related_words = ARRAY['전자상거래','전자금융']::text[] WHERE id = 505;  -- 전자화폐
UPDATE public.words SET meaning = '시장에서 거래의 당사자인 쌍방 간의 상호작용에 필요한 정보량에 차이가 있는 경우를 말한다.', detailed_meaning = '시장에서 거래의 당사자인 쌍방 간의 상호작용에 필요한 정보량에 차이가 있는 경우를 말한다. 이러한 정보의 비대칭성(Information Asymmetry)은 효율적인 자원배분을 불가 능하게 하며 역선택(adverse selection)이나 도덕적 해이(moral hazard) 등의 문제를 낳는다. 역선택은 중고차시장의 경우와 같이 판매자가 파는 물건의 속성에 대해 구매자보다 정보가 많을 때 생기는데 이런 상황에서는 판매자가 구매자에게 품질이 낮은 물건을 시장에 아예 내놓지 않게 되거나, 구매자가 좋지 않은 물건을 비싸게 사게 된다. 노동시장이나 보험시장에서도 역선택이 문제가 되는데, 노동시장의 경우 기업이 근로자의 생산성을 잘 알 수 없어 시장균형이 사회적으로 비효율적인 상태가 될 수 있으며 보험시장의 경우에는 사고를 당할 가능성이 낮은 사람들은 보험조건이 자신들에게 불리하기 때문에 아예 보험에 가입하지 않게 되는 문제가 생긴다. 도덕적 해이는 대리인이 사용자를 위해 어떤 임무를 수행할 때 발생하는 문제로, 대리인의 부적절하거나 비도적적인 행위에 따른위험을 지칭한다. 자동차보험에 가입한 후 안전운전을 소홀히 하거나, 국민건강보험이 잘되어 있다고 해서 특별한 이상이 없는데도 병원에 자주 가는 것 등은 도덕적 해이의 예이 다. 도덕적 해이를 방지하기 위해 사용자는 대리인이 보다 성실하게 행동하도록 인센티브를 지급하거나 감시체계를 구축하는 등의 방법을 활용한다.', related_words = ARRAY['도덕적 해이','정부실패']::text[] WHERE id = 509;  -- 정보의 비대칭성
UPDATE public.words SET meaning = '정부의 재정활동과 관련하여 발생하는 모든 국고금의 수입과 지출을 관리하는 계정을 정 ㅈ부당좌예금계정이라 한다.', detailed_meaning = '정부의 재정활동과 관련하여 발생하는 모든 국고금의 수입과 지출을 관리하는 계정을 정 ㅈ부당좌예금계정이라 한다. 동 계정은 한국은행 본부에만 설치되어 있는데 한국은행 본부및 지역본부, 한국은행 국고대리점 및 체신관서 등에서 취급하는 수입금 및 지출금 등 일체의 국고금 수급 내역이 계상된다. 그러나 2003년 「국고금 관리법」의 제정으로 예외조 항이 신설됨에 따라 당행 외에 금융기관에도 예치가 가능해져 현재 금고은행에 일부 기금이 예탁되어 있다. 당행은 동 계정의 수급내역을 명확히하기 위해 일반회계, 특별회계, 기금 및 특별계정으로 구분하여 관리한다. 일반회계는 국가예산의 근간이 되는 것으로서 주로 조세와 같은 일반 세입과 국가기능 유지를 위한 일반 지출을 회계처리하기 위한 용도 이며, 특별회계는 국가가 특정사업(우편·양곡·조달관리 등)을 운영하고자 하거나, 특정한 세입으로 특정한 세출에 충당하고자 할 때 일반회계와 구분하여 회계처리하기 위한 용도이다. 기금은 특정한 분야의 사업에 대하여 지속적이고 안정적인 자금 지출이 필요하거나, 개별 법률에 의해 탄력적인 집행이 필요한 경우에 회계처리하기 위한 용도이고, 특별계정은 국고금 수급에 수반되는 자금의 흐름을 그 성격에 따라 명확하게 구분·회계처리하기 위한 용도이며 세입·세출과는 무관하게 이루어진다.', related_words = ARRAY['국고대리점']::text[] WHERE id = 510;  -- 정부당좌예금계정
UPDATE public.words SET meaning = '정부의 주택 정책목표(주거복지 증진과 대출 접근성 제고)를 달성하기 위해 정부재정을 직·간접적으로 투입하여 주택금융공사와 주택도시기금으로 하여금 구입 주택 혹은 전월세 보증금을 담보로 시중보다', detailed_meaning = '정부의 주택 정책목표(주거복지 증진과 대출 접근성 제고)를 달성하기 위해 정부재정을 직·간접적으로 투입하여 주택금융공사와 주택도시기금으로 하여금 구입 주택 혹은 전월세 보증금을 담보로 시중보다 낮은 금리로 관련 주택자금을 제공하도록 하는 다양한 주택관련 정책대출 상품(보금자리론, 디딤돌대출, 버팀목대출 등)을 의미한다. 정책모기지는 취약계층과 서민·실수요층의 주거 안정을 지원하고 주택자금 상환부담을 낮추는 한편 안심전환대출 등을 통해 주택담보대출에서 고정금리·분할상환 대출이 차지하는 비중을 높임으로써 가계부채의 질적 구조를 개선하는데 기여하고 있다. 또한 저출산·인구구조 변화에 대응하기 위해 청년·신혼부부·출산가구로 공급대상을 확대하고 지원대상 요건(연소득, 주택가격 등)도 완화하였다. 한편 보증의 형태로 주택자금을 공급하는 경우까지 포함 할 경우 주택 정책금융이란 용어를 사용하고 있다.', related_words = ARRAY['모기지대출']::text[] WHERE id = 512;  -- 정책모기지/주택 정책대출
UPDATE public.words SET meaning = '정책시차(Policy Lag)란 어떤 경제정책을 시행해야 하는 원인이 발생하여 동 정책을 집행하는 데까지 걸리는 시간과 정책이 실제로 집행된 후 정책효과가 나타나는 데 걸리는 시간을 말한다.', detailed_meaning = '정책시차(Policy Lag)란 어떤 경제정책을 시행해야 하는 원인이 발생하여 동 정책을 집행하는 데까지 걸리는 시간과 정책이 실제로 집행된 후 정책효과가 나타나는 데 걸리는 시간을 말한다. 전자를 내부시차(inside lag)라 하고 후자를 외부시차(outside lag)라고 한 다. 일반적으로 재정정책은 정책이 집행되기까지의 내부시차가 긴 반면, 정책효과가 나타나는 데 걸리는 외부시차는 짧다. 그 이유는 정부지출이나 조세제도를 변경하려면 시간이 걸리는 입법 절차를 거쳐야 하지만, 일단 정책이 집행되고 나면 총수요에 직접적인 영향을 미치기 때문이다. 한편, 통화정책의 경우는 재정정책과는 달리 내부시차는 짧지만, 생산, 물가 등 실물변수에 영향을 미치는 데는 상당한 시간이 걸리는 등 외부시차가 상대적으로 길다. 예컨대 통화정책으로 기준금리가 인하되고 그것이 금융·외환시장을 거쳐 실물부문의 가계 소비나 기업 투자 등으로 파급되기까지는 상당한 시간이 걸릴 수 있다.', related_words = ARRAY['재정정책']::text[] WHERE id = 513;  -- 정책시차
UPDATE public.words SET meaning = '한국전쟁의 여파로 산업활동이 크게 위축되고 물가가 급등하는 등 경제가 큰 혼란에 빠짐에 따라 이를 타개하기 위하여 1953년 2월 15일 화폐단위를 ‘원(圓)’에서 ‘환(圜)’으로 변경하고', detailed_meaning = '한국전쟁의 여파로 산업활동이 크게 위축되고 물가가 급등하는 등 경제가 큰 혼란에 빠짐에 따라 이를 타개하기 위하여 1953년 2월 15일 화폐단위를 ‘원(圓)’에서 ‘환(圜)’으로 변경하고 100대 1로 절하(100圓 → 1圜)하는 긴급통화조치를 단행하였다. 1953년 2월 17일부터 ‘圓’표시 한국은행권의 유통을 중지시켰으며 그 동안 한국은행권과 함께 저액면용으로 통용되어 오던 7종류 조선은행권(10圓, 5圓, 1圓, 50錢, 20錢, 10錢 및 5錢)과 일본정부의 소액보조화폐(1錢주화)의 유통도 전면 중지하고 환(圜) 표시 한국은행권만을 유일한 법화로 인정함으로써 우리나라 화폐의 완전한 독자성이 확보되었다.', related_words = ARRAY['제2차 통화조치']::text[] WHERE id = 514;  -- 제1차 통화조치
UPDATE public.words SET meaning = '정부는 1962년부터 「경제개발 5개년 계획」을 추진하면서 퇴장자금의 산업 자금화 등을 위하여 1962년 6월 10일 긴급통화조치를 단행하여 화폐단위를‘환(圜)’에서 ‘원’으로 변경하고 10대', detailed_meaning = '정부는 1962년부터 「경제개발 5개년 계획」을 추진하면서 퇴장자금의 산업 자금화 등을 위하여 1962년 6월 10일 긴급통화조치를 단행하여 화폐단위를‘환(圜)’에서 ‘원’으로 변경하고 10대 1로 절하(10圜 → 1원)하고 ‘환(圜)’ 표시 화폐의 유통과 거래를 금지하였다 (단, 50환화와 10환화는 1975년 3월 21일까지 유통). 한국은행은 긴급통화조치에 의해 500원권, 100원권, 50원권, 10원권, 5원권 및 1원권 등 6종의 새로운 은행권을 발행하고 소액거래시 1원 미만 끝자리수 처리의 편의를 도모하기 위하여 1962년 12월 1일에 10전권과 50전권도 발행하였다. 본 조치는 경제적 목적 달성보다는 ‘원’표시 도입이라는 의의를 가진다.', related_words = ARRAY['제1차 통화조치']::text[] WHERE id = 515;  -- 제2차 통화조치
UPDATE public.words SET meaning = '금융기관 간에 여유자금과 부족자금을 빌리는 단기금융시장에서 거래되는 초단기 자금의 금리(한국과 일본의 콜금리, 미국의 페더럴펀드금리 등)를 0%에 가까운 수준으로 떨어뜨리는 통화정책을 말한다.', detailed_meaning = '금융기관 간에 여유자금과 부족자금을 빌리는 단기금융시장에서 거래되는 초단기 자금의 금리(한국과 일본의 콜금리, 미국의 페더럴펀드금리 등)를 0%에 가까운 수준으로 떨어뜨리는 통화정책을 말한다. 중앙은행이 단기금리를 제로 근처로 유도하는 것은 시중 유동성을 풍부하게 하여 금융경색을 억제하고 경기침체를 극복하기 위한 목적인 것이 보통이다. 일본의 경우 1999년 초 일본은행이 경기활성화를 위해 콜금리를 0.02%까지 떨어뜨리며 제로금리정책을 펼쳤으나 당초 기대만큼 소비나 투자활성화가 이루어지지 않아 2006년7월 제로금리정책을 폐기한 바 있다. 이와 관련하여 2001년 3월 일본은행은 장기간의 경기침체에서 벗어나기 위해 양적완화(QE; Quantitative Easing) 정책을 처음으로 도입했 다. 양적완화는 금리가 제로(‘0’)에 가까운 상태에서 경기부양을 위해 국채 등 다양한 금융자산의 매입을 통해 시중에 돈을 공급하는 것이다. 중앙은행이 금리를 조절해 간접적으로 시중 유동성을 조절하던 전통적인 방식과 달리 양적완화는 금융자산 등을 사들이는 방법으로 시장에 통화량 자체를 늘리는 정책인데 2008년 글로벌 금융위기 이후 미국, EU, 영국 등 국제적으로 도입이 확산돼 왔다. 2008년 12월 글로벌 금융위기로 미국도 제로금리를 도입하였다.', related_words = ARRAY['양적완화정책']::text[] WHERE id = 516;  -- 제로금리정책
UPDATE public.words SET meaning = '생산능력지수는 공급능력의 수준과 동향이 어떻게 변화하는가를 나타낸 것이며, 가동률 ㅈ지수는 생산실적과 생산능력의 비율인 설비이용도를 지수화한 것으로서 경기동향 분석의 기초 자료로 이용된다.', detailed_meaning = '생산능력지수는 공급능력의 수준과 동향이 어떻게 변화하는가를 나타낸 것이며, 가동률 ㅈ지수는 생산실적과 생산능력의 비율인 설비이용도를 지수화한 것으로서 경기동향 분석의 기초 자료로 이용된다. 두 지수는 공급능력과 설비가동의 절대수준을 나타내는 것이 아니 라 기준년도의 생산능력과 가동률을 100으로 하였을 때 비교시의 공급능력과 가동상태가 어느 수준인가를 나타낸다. 일반적으로 생산은 자가소비, 출하 및 재고변동의 합으로 표현하는데 출하가 생산보다 경기에 대해 민감(선행)한 경향이 있다. 따라서 경기가 하강하는 경우 출하는 즉시 감소하나 기업이 생산을 급격히 감소시키기 어려우므로 재고가 증가 하게 된다. 반대로 경기가 회복되는 경우 출하가 증가하면서 재고가 감소하고 뒤따라 생산이 증가하게 된다. 한편, 가동률은 경기의 움직임에 따라 변동한다. 가동률 = 생산실적/생산능력×100', related_words = ARRAY['제조업평균가동률갭']::text[] WHERE id = 517;  -- 제조업생산능력/가동률지수
UPDATE public.words SET meaning = '전략적 상황에 처한 경제주체들의 행동을 분석하는데 유용하게 활용되는 게임이론의 한 예로서, 협력적인 선택이 양자에게 최선임에도 불구하고 자신의 이익에 치중한 선택으로 ㅈ인해 오히려 두 사람', detailed_meaning = '전략적 상황에 처한 경제주체들의 행동을 분석하는데 유용하게 활용되는 게임이론의 한 예로서, 협력적인 선택이 양자에게 최선임에도 불구하고 자신의 이익에 치중한 선택으로 ㅈ인해 오히려 두 사람 모두에게 바람직하지 않은 결과를 가져오는 상황을 말한다. 죄수의 딜레마(Prisoners’ Dilemma)는 1950년 미국 프린스턴대 터커(A. Tucker) 교수가 게임 이론을 설명하기 위해 이용한 다음의 예화에서 비롯되었다. 경찰이 두 용의자 Ⅰ, Ⅱ를 격리하여 심문하면서 자백을 이끌어 내려고 다음과 같이 말하였다고 가정한다. ① 한 사람이 자백하고 다른 사람은 입을 다물었다면 자백한 사람은 1단위의 보상, 입을 다문 사람은 2단위의 벌금형이 부과된다. ② 두 사람이 모두 자백하면 각각에게는 1단위의 벌금형이 부과된다. ③ 두 사람이 모두 자백하지 않으면 Ⅰ과 Ⅱ는 혐의가 없다. 이러한 상황에서 두 사람이 직면하는 보상행렬은 아래와 같아지는데, Ⅰ과 Ⅱ는 모두 상대방의 전략과 상관없이 자백하는 전략을 선택하게 되므로 결과적으로 두 사람이 서로를 믿고 자백하지 않는 전략을 취할 때보다 나쁜 결과에 직면하게 된다. 용의자 Ⅱ 구분자백함 자백하지 않음 자백함 (-1, -1) (1, -2) 용의자 Ⅰ자백하지 않음 (-2, 1) (0, 0) 즉 개인적인 수준에서는 합리적인 선택이 구성원 전체로 보아서는 비합리적인 선택이 되는 결과를 가져오는 딜레마를 낳게 되는데, 이 같은 죄수의 딜레마 문제는 광고경쟁, 기업의 환경오염, 국가간 군비경쟁 등 다양한 상황에 적용될 수 있다.', related_words = ARRAY['치킨게임']::text[] WHERE id = 521;  -- 죄수의 딜레마
UPDATE public.words SET meaning = '주가순자산비율(PBR; Price to Book Ratio)은 주가를 주당순자산가치(BPS; Book- value Per Share)로 나눈 비율이다.', detailed_meaning = '주가순자산비율(PBR; Price to Book Ratio)은 주가를 주당순자산가치(BPS; Book- value Per Share)로 나눈 비율이다. 즉 기업의 순자산에 비해 주가가 얼마나 높은지 또는 낮은지를 나타내는 지표이다. 대부분의 성공적인 기업의 경우 주가순자산비율이 1을 크게 상회하는데, 이는 시장이 해당 기업의 미래 성장성과 수익성을 높게 평가하고 있음을 의미한다. 기업별로 이 비율이 다른 것은 경영성과, 성장 가능성, 산업 특성 등 기업 고유의 가치 차이가 반영되기 때문이다. 증권분석가들은 종종 주가순자산비율이 낮은 주식을 가치주식, 높은 주식을 성장주식으로 분류하기도 한다.', related_words = ARRAY['주가수익비율(PER)']::text[] WHERE id = 522;  -- 주가순자산비율(PBR)
UPDATE public.words SET meaning = '주가지수옵션(Stock Index Options)은 주가지수(기초자산)를 만기일에 사전에 약정한 가격(행사가격)으로 매입하거나 매도할 수 있는 권리를 거래하는 파생금융상품으로서 매입권리인', detailed_meaning = '주가지수옵션(Stock Index Options)은 주가지수(기초자산)를 만기일에 사전에 약정한 가격(행사가격)으로 매입하거나 매도할 수 있는 권리를 거래하는 파생금융상품으로서 매입권리인 콜옵션(call option)과 매도권리인 풋옵션(put option)으로 구분된다. 옵션의 매도자는 매수자에게 옵션을 제공하고 매수자는 그 대가로 프리미엄(옵션가격)을 지급한다. 콜옵션 매수자는 만기일에 기초자산가격(코스피200 종가 등)이 행사가격을 넘어서 면 권리를 행사할 유인이 발생하며, 기초자산가격이 행사가격에 프리미엄을 더한 값을 초과하는 금액만큼 매수자의 이익(매도자의 손실)이 된다. 풋옵션 매수자는 만기일에 기초자산가격(코스피200 종가 등)이 행사가격보다 낮아야만 권리를 행사할 유인이 발생하며, 기초자산가격이 행사가격에서 프리미엄을 차감한 값을 하회하는 금액만큼 풋옵션 매수자의 이익(매도자의 손실)이 된다. 주가지수옵션은 주가지수선물과 마찬가지로 실물이 존재하지 않는 주가지수를 대상으로 하고 있으나 거래의 목적물이 권리라는 점에서 주가지수선물과 다르다. 또한 주가지수옵션은 주가지수선물과 달리 기초자산 가격변동에 따른 손익구조가 비대칭적이다. 옵션매수자는 손실이 프리미엄으로 한정되는 반면 이익은 기초자산가격에 비례하여 증가하고, 역으로 옵션매도자는 이익이 프리미엄에 국한되는 반면손실은 제한이 없다. 주가지수옵션시장은 1983년 3월 미국의 시카고옵션거래소(CBOE; Chicago Board Options Exchange)에서 S&P100지수를 대상으로 최초로 개설되었으며 우리나라에서는 1997년 7월에 코스피200 옵션시장이, 2001년 11월에 코스닥50 옵션시장이 개설되었다. ㅈ', related_words = ARRAY['주가지수선물거래']::text[] WHERE id = 526;  -- 주가지수옵션
UPDATE public.words SET meaning = '주당순이익(EPS; Earning Per Share)은 기업이 벌어들인 당기순이익을 동 기업이 발행한 총 주식수로 나눈 값을 말한다.', detailed_meaning = '주당순이익(EPS; Earning Per Share)은 기업이 벌어들인 당기순이익을 동 기업이 발행한 총 주식수로 나눈 값을 말한다. 당기순이익(net income)은 손익계산서상 계속사업손익과 중단사업손익을 합산하여 산출된 최종손익을 의미하며, 해당 회계연도의 최종적인경영성과를 나타낸다. 따라서 EPS는 통상 1년 동안 기업이 주식 1주당 얼마나 많은 이익을 창출했는지를 나타내는 지표가 된다. EPS가 높다는 것은 그만큼 기업의 경영실적이 양호하고 배당여력도 많다는 것을 의미하므로, 주가의 상승요인으로 작용하게 된다. EPS는 당기순이익 규모가 증가하면 높아진다. 한편, 전환사채(CB; Convertible Bond)의 주식전환이나 증자로 주식수가 늘어나면 EPS는 낮아지게 된다. EPS는 기업의 수익성을 분석하는 중요한 지표이며, 주가수익비율(PER) 계산의 기초가 된다. 개별 기업의 EPS 증가는 동 기업의 시장지배력이 확대되는 것으로 이해된다. 전체 산업의 EPS 증가는 신기술 개발이나 신제품 출시 등 기술혁신이 활발히 이루어지고 있다는 신호로 해석될 수 있다.', related_words = '{}'::text[] WHERE id = 527;  -- 주당순이익(EPS)
UPDATE public.words SET meaning = '주택저당증권(MBS; Mortgage-Backed Securities)이란 자산유동화증권(ABS)의 일종으로써 모기지(또는 주택담보대출)를 기초자산으로 발행되는 증권이다.', detailed_meaning = '주택저당증권(MBS; Mortgage-Backed Securities)이란 자산유동화증권(ABS)의 일종으로써 모기지(또는 주택담보대출)를 기초자산으로 발행되는 증권이다. 원래 주택저당증권은 미국에서 제2차 세계대전 이후 참전한 군인들의 주거 안정을 위해 도입된 제도 인데 우리나라에서는 IMF 외환위기 이후 본격적으로 취급되기 시작하였다. MBS시장은 세 종류의 시장으로 구분되는데 1차 시장은 모기지 차입자와 모기지 대출기관 사이에 모기지론이 이루어지는 시장이며, 2차 시장은 모기지 대출기관이 보유하고 있는 모기지를 유동화(증권화)하는 시장이며 자본시장은 모기지가 유동화된 주택저당증권이 투자자에 게 매각되고 유통되는 시장을 말한다. 주택저당증권은 일반 채권과는 다른 특징을 보유하고 있다. 보통 채권은 발행자가 원리금 상환을 부담하는데 반해 MBS는 통상 기초자산을 특수목적회사(SPC)에 이전하고 SPC가 발행하는 것이기 때문에 원리금 상환이 발행자의 신용에 기초하기보다는 기초자산의 현금 흐름에 의존하게 된다. 또한 MBS에는 조기상환위험(prepayment risk)이라는 독특한 위험이 존재한다. 시장금리가 하락하는 경우에는 기존 모기지 차입자가 이자비용 절감을 위해 동 모기지를 조기에 상환하고 금리가 더 낮은 모기지론을 받게 되는데 모기지 상환이 이루어지면 그것을 기초자산으로 하 ㅈ고 있는 MBS도 조기에 상환이 이루어지게 된다. 이것을 투자자 입장에서 보면 자산 듀레이션이 당초 예상보다 줄어들어 국채 추가 매입 등 자산 듀레이션을 더 늘려야 하는 문제(반대로 시장금리가 상승하는 경우에는 자산 듀레이션이 당초 예상보다 늘어나 보유채권 매각 등 자산 듀레이션을 줄여야 하는 문제)를 야기한다. 그래서 투자자는 MBS를 투자할 때는 적정 조기상환율을 산정하고 이를 토대로 투자를 하게 된다. 은행이 보유하고 있는 모기지를 유동화하는 경우 모기지론에서 발생하는 이자수익은 줄어들지만 매각대금으로 모기지를 추가로 취급할 수 있는 여력이 생기며 위험자산이 줄어들기 때문에 BIS비율이 올라가는 긍정적인 효과를 기대할 수 있다. 현재 우리나라에서는 은행이 모기지론을 취급하며 한국주택금융공사가 동 모기지를 유동화하여 자본시장에 매각하는 형태로 이루어지고 있다.', related_words = ARRAY['자산유동화','모기지대출']::text[] WHERE id = 530;  -- 주택저당증권(MBS)
UPDATE public.words SET meaning = '물품을 수입하되 이를 국내에 반입하지 아니하고 가공하지 않은 원형 그대로 직접 제3 국으로 수출하는 형태의 무역거래를 말한다.', detailed_meaning = '물품을 수입하되 이를 국내에 반입하지 아니하고 가공하지 않은 원형 그대로 직접 제3 국으로 수출하는 형태의 무역거래를 말한다. 중계무역업자는 수출입의 당사자로서 자기 책임 하에 수입 및 수출을 하고 대금결제를 한다는 점에서 수출입의 주체가 되지 않고 단순히 중개수수료만을 취득하는 중개무역과 구분된다.', related_words = ARRAY['중개무역']::text[] WHERE id = 533;  -- 중계무역
UPDATE public.words SET meaning = '중앙거래당사자(CCP; Central Counterparty)는 증권거래 계약의 매도자에 대해 매수자역할을, 매수자에 대해서는 매도자 역할을 수행하는 기관으로서 다자간 차감에 의한 청산업무를', detailed_meaning = '중앙거래당사자(CCP; Central Counterparty)는 증권거래 계약의 매도자에 대해 매수자역할을, 매수자에 대해서는 매도자 역할을 수행하는 기관으로서 다자간 차감에 의한 청산업무를 수행하여 결제 유동성을 절약하는 한편 결제이행보증 서비스를 제공하여 참가자의 리스크관리 부담을 경감시키고 신용 및 유동성리스크를 집중하여 관리하는 역할을 수행하고 있다. 한편 글로벌 금융위기 이후 모든 표준화된 장외파생상품거래의 중앙거래당사자를 통한 청산이 의무화됨에 따라 결제리스크가 집중되는 중앙거래당사자에 대한 리스크 관리의 중요성이 더욱 커지고 있다. 우리나라의 장내 증권 및 파생상품 거래는 한국거래소가 중앙거래당사자 역할을 수행하고 있다. 장외거래의 경우 금융위원회로부터 금융투자상품거래청산업 인가를 받은 한국거래소와 한국예탁결제원이 각각 장외파생상품거래(원화 이자율스왑거래)와 주식기관투자자거래(상장주식의 위탁매매거래)에 대해 중 ㅈ앙거래당사자의 역할을 하고 있다.', related_words = ARRAY['지급결제시스템']::text[] WHERE id = 534;  -- 중앙거래당사자
UPDATE public.words SET meaning = '중앙예탁기관(CSD; Central Securities Depository)은 각종 증권을 집중적으로 예탁받아 관리하는 기관으로서, 증권 발행 및 유통시장에서 예탁자와 예탁자의 고객을 대상으로', detailed_meaning = '중앙예탁기관(CSD; Central Securities Depository)은 각종 증권을 집중적으로 예탁받아 관리하는 기관으로서, 증권 발행 및 유통시장에서 예탁자와 예탁자의 고객을 대상으로 증권의 예탁, 계좌대체, 예탁증권의 권리행사 등의 업무를 수행한다. 또한 중앙예탁기관은 금융시장에서 거래되는 증권을 집중 보관함으로써 증권결제가 실물증권의 이동 없이 계좌대체방식으로 이루어질 수 있도록 한다. 금융시장의 증권결제는 대부분 계좌대체방식으로 이루어지고 있으므로 중앙예탁기관은 통상 증권매매거래의 결제 과정에서 증권이전(delivery)을 책임지는 기관으로서의 역할을 수행하고 있다. 현재 각국에서는 단일이 나 소수의 중앙예탁기관이 증권의 예탁 및 이전 업무를 수행하고 있으며 우리나라에서는 한국예탁결제원이 동 업무를 수행하고 있다.', related_words = ARRAY['계좌대체']::text[] WHERE id = 535;  -- 중앙예탁기관
UPDATE public.words SET meaning = '중앙은행 디지털화폐(CBDC; Central Bank Digital Currency)는 중앙은행 내 지준예치금이나 결제성 예금과는 별도로 중앙은행이 발행하는 새로운 전자적 형태의 화폐를 의 미한다.', detailed_meaning = '중앙은행 디지털화폐(CBDC; Central Bank Digital Currency)는 중앙은행 내 지준예치금이나 결제성 예금과는 별도로 중앙은행이 발행하는 새로운 전자적 형태의 화폐를 의 미한다. 2010년대 중반 비트코인과 분산원장기술이 주목을 받기 시작한 이후 중앙은행디지털화폐에 대한 관심이 크게 증대되었으며 2015년 영란은행이 CBDC란 용어를 최초로 사용하였다. 한편 이용주체에 따라 모든 경제주체가 이용할 수 있는 소액결제용 CBDC 와 금융기관이 이용하는 거액결제용 CBDC로 구분하며 구현방식에 따라 현재와 같은 계좌방식의 단일원장방식과 분산원장방식으로 구분된다. 다만 단일원장기반 거액결제용CBDC는 기존의 지준예치금 이나 결제성예금과 개념상 동일하므로 국제기구 등에서는 분산원장기반 거액결제용 CBDC만을 거액결제용 CBDC로 분류한다. 최근 들어 글로벌 빅테크 기업 등이 발행한 스테이블코인의 확산 가능성 및 부작용에 대한 우려가 커짐에 따라중앙은행에 대한 신뢰를 기반으로 발행되는 CBDC에 대한 관심이 더욱 높아지고 있다.', related_words = ARRAY['스테이블코인','분산원장 기술','지준예치금']::text[] WHERE id = 537;  -- 중앙은행 디지털화폐(CBDC)
UPDATE public.words SET meaning = '증권대금동시결제(DVP; Delivery versus Payment)는 중앙예탁기관의 증권결제시스템을 대금결제은행의 지급시스템과 연계하여 증권 인도를 전제로 자금을 지급하거나 자금지급을 전제로', detailed_meaning = '증권대금동시결제(DVP; Delivery versus Payment)는 중앙예탁기관의 증권결제시스템을 대금결제은행의 지급시스템과 연계하여 증권 인도를 전제로 자금을 지급하거나 자금지급을 전제로 증권을 인도하는 방식이다. 이 방식은 증권인도시기와 대금지급시기가 서 로 달라 거래당사자중 한쪽이 계약을 불이행할 경우 발생하는 원금리스크를 근본적으로 제거할 수 있기 때문에 증권결제리스크를 관리하는 데 효과적이다. 「지급결제 및 시장인프라위원회」(CPMI)와 「국제증권감독기구」(IOSCO)에서 제정한 국제기준인 「금융시장인프라에 관한 원칙」(PFMI)에서도 증권결제시스템은 DVP방식을 이용함으로써 원금리스크를 제거하도록 권고하는 등 국제적으로 증권결제시스템이 준수해야 할 결제표준이 되고 있다. 우리나라의 경우 장내 주식거래와 장내국채 및 RP거래, 장외채권거래 등 주요 증권거래에 대하여 한은금융망과 한국예탁결제원의 증권결제시스템을 연계하여 DVP 방식으로 결제하고 있다.', related_words = ARRAY['분리결제','외환동시결제(PVP)']::text[] WHERE id = 540;  -- 증권대금동시결제(DVP)
UPDATE public.words SET meaning = '증권커스터디서비스는 유가증권에 투자하는 투자자를 대신하여 해당 증권의 보고 (safekeeping) 및 기록(record keeping), 이전(delivery), 원리금 및 배당금 수령, 통지등', detailed_meaning = '증권커스터디서비스는 유가증권에 투자하는 투자자를 대신하여 해당 증권의 보고 (safekeeping) 및 기록(record keeping), 이전(delivery), 원리금 및 배당금 수령, 통지등 제반 관리서비스를 제공하는 업무를 말한다. 예를 들어, 외국인 투자자가 국내 증권에 투자할 때 시중은행 및 외국계은행 등의 커스터디기관이 실물증권 반출의 어려움이나 법적·행정적 복잡성을 해소해 주는 증권커스터디서비스를 제공하고 있다. 또한 외국 중앙은 행이 국내 채권에 투자할 경우, 커스터디기관인 한국은행을 통해 보호예수, 원리금 수령, 매매대금 결제, 환전, 여유자금 운용 등의 서비스를 이용할 수 있다. 이처럼 증권커스터디서비스는 투자자 자산을 외부 도난, 해킹, 분실 등 위험으로부터 보호하고, 법적·기술적안전성을 제공한다.', related_words = '{}'::text[] WHERE id = 541;  -- 증권커스터디서비스
UPDATE public.words SET meaning = '증시주변자금은 주식시장에 직접 투자되지는 않지만, 언제든지 유입될 수 있는 대기성 자금이다.', detailed_meaning = '증시주변자금은 주식시장에 직접 투자되지는 않지만, 언제든지 유입될 수 있는 대기성 자금이다. MMF, CMA, 예탁금, 펀드 대기자금, 투자자 예수금 등이다. 증시 호조 기대시 이 자금이 주식시장으로 유입되어 지수 상승에 기여할 수 있다. 시장의 유동성과 투자 여력, 투자 심리 등을 파악하는데 중요한 지표로 활용된다.', related_words = '{}'::text[] WHERE id = 542;  -- 증시주변자금
UPDATE public.words SET meaning = '국제결제은행(BIS)의 「지급 및 시장인프라 위원회」 (CPMI; Committee on Payments and Market Infrastructures)는 1990년 설립된', detailed_meaning = '국제결제은행(BIS)의 「지급 및 시장인프라 위원회」 (CPMI; Committee on Payments and Market Infrastructures)는 1990년 설립된 「지급결제제도위원회」(CPSS; Committee on Payment and Settlement Systems)의 명칭을 2014년 9월 1일부터변경한 것으로, 처음에는 주요국의 지급결제제도 동향을 모니터링하고 분석하기 위해 설립되었다. 현재는 「금융시장인프라에 관한 원칙」 등 국제기준 제정 및 이행상황 모니터링, 금융시장인프라 감시와 관련한 정책 개발 및 제안 주도, 중앙은행 간 협력 증진 및 정보교환 촉진 등의 기능을 수행하고 있다. 2022년 9월말 현재 CPMI에는 28개국 중앙은행이 참여 중이며 한국은행은 2009년 7월 24일 회원으로 가입하였다.', related_words = ARRAY['국제결제은행(BIS)','지급결제시스템']::text[] WHERE id = 543;  -- 지급결제 및 시장인프라 위원회 (BIS CPMI)
UPDATE public.words SET meaning = '개인·기업·정부 등 경제주체들의 금융거래나 경제활동에서 발생하는 지급, 청산 및 결제가 원활히 이루어지도록 해주는 금융시스템의 하부구조로서 중앙은행, 은행, 청산기관, 관련 법규, 지급수단 등으로', detailed_meaning = '개인·기업·정부 등 경제주체들의 금융거래나 경제활동에서 발생하는 지급, 청산 및 결제가 원활히 이루어지도록 해주는 금융시스템의 하부구조로서 중앙은행, 은행, 청산기관, 관련 법규, 지급수단 등으로 구성된다. 지급결제시스템은 시장경제 하에서 각종 경제활동이 실행되는 금융 하부구조로서 기능하기 때문에 효율적이고 안정적인 지급결제시스템은 금융제도의 발전과 건전한 신용질서를 유지하기 위한 근간이 된다.', related_words = ARRAY['거액지급시스템','소액지급시스템','지급수단']::text[] WHERE id = 545;  -- 지급결제시스템
UPDATE public.words SET meaning = '국제결제은행(BIS)의 지급결제 및 시장인프라 위원회는 지급결제제도 감시(Oversight of Payment Systems)를 “기존 시스템 및 구축 예정인 시스템을 모니터링하고 동 시스템에', detailed_meaning = '국제결제은행(BIS)의 지급결제 및 시장인프라 위원회는 지급결제제도 감시(Oversight of Payment Systems)를 “기존 시스템 및 구축 예정인 시스템을 모니터링하고 동 시스템에 대해 평가하는 한편, 필요시 개선을 유도함으로써 동 시스템들의 안전성 및 효율성의 증진을 도모하는 중앙은행의 기능”으로 정의하고 있다. 즉, 지급결제제도 감시의 개념에는 공공정책 목표(안전성 및 효율성), 감시범위(지급결제시스템), 감시활동(모니터링, 평가 및 개선 권고)의 세 가지 요소와 지급결제제도에 대한 중앙은행의 책무라는 의미가 함께 들어 있다. 지급결제제도에 대한 중앙은행의 감시가 필요한 이유는 시장경제가 원활하게작동하는 데 있어 지급결제시스템의 역할이 매우 중요하기 때문이다. 경제적 거래에 수반되는 자금, 증권 및 외환의 이동은 대부분 지급결제시스템을 통해 이루어지기 때문에 원활한 지급결제는 시장이 제 기능을 하는 데 필수적이다. 또한 대부분의 지급결제시스템은 민간부문에 의해 구축·운영되는 것이 일반적인데 일부 시스템의 경우 시장실패로 인해 사회적으로 최적수준의 안전성과 효율성을 달성하지 못할 가능성이 있어 공공부문의 개입이 필요하게 된다.', related_words = ARRAY['지급결제 및 시장인프라 위원회(BIS CPMI)','결제리스크']::text[] WHERE id = 546;  -- 지급결제제도 감시
UPDATE public.words SET meaning = '지급준비자산제도란 한국은행이 필요하다고 인정될 때 금융기관에 대하여 예금지급준비금과는 별도의 지급준비자산을 보유할 수 있는 제도(「한국은행법」 제63조)이다.', detailed_meaning = '지급준비자산제도란 한국은행이 필요하다고 인정될 때 금융기관에 대하여 예금지급준비금과는 별도의 지급준비자산을 보유할 수 있는 제도(「한국은행법」 제63조)이다. 지급준비자산에는 현금, 국채, 정부보증채 및 한국은행이 발행하는 통화안정증권 등이 있다. 원래 동 제도는 전통적인 예금지급준비제도를 보완하는 한편 금융기관으로 하여금 국채 등 유가증권을 보유토록 함으로써 국채 등에 대한 수요를 강화시켜 공개시장운영 기반을 마련하기 위해 도입되었다. 통상 지급준비금에 대해서는 이자를 지급하고 있지 않기 때문에 그만큼 기회비용이 발생하게 된다. 그러나 이를 유가증권 등으로 보유하게 되면 수익이 발생함에 따라 지급준비금 보유에 따른 기회비용을 줄일 수 있어 은행의 재무건전성이 제고될 수 있고 지급준비금 보유의무가 없는 비은행금융기관과의 형평성 문제도 줄어들 수있다. 그러나 동 제도는 채권시장의 유통물량을 축소시키는 등 금융시장을 위축시킬 수있으므로 금융시장 여건을 면밀히 고려하여 시행되어야 한다.', related_words = '{}'::text[] WHERE id = 549;  -- 지급준비자산제도
UPDATE public.words SET meaning = '지방은행공동망은 지방은행이 공동으로 운영하는 지급시스템인 뱅크라인(Bankline) 업무를 처리하는 공동망으로서 1997년 6월 가동되었다.', detailed_meaning = '지방은행공동망은 지방은행이 공동으로 운영하는 지급시스템인 뱅크라인(Bankline) 업무를 처리하는 공동망으로서 1997년 6월 가동되었다. 동 시스템의 가동으로 전국적인 영업망을 갖추지 못한 지방은행들도 전국의 고객을 대상으로 예금의 입·출금 및 계좌조회서비스를 제공할 수 있게 되었다. 2017년말 현재 지방은행공동망에는 6개 지방은행이 모두 참여하고 있다. 지방은행공동망의 업무는 입금업무와 출금업무로 구분된다. 입금업무는 타행환공동망과 유사하게 다른 지방은행 계좌로 입금 처리하는 업무이며, 출금업무는 CD공동망과 유사한 방식으로 다른 지방은행의 통장을 소지한 고객에게 출금 처리하는 업무이다. 지방은행공동망의 가동시간은 기본적으로 은행 영업시간과 동일한 09시부터 16시까지이며 전산장애 등으로 운영시간 연장이 불가피한 경우에는 금융결제원이 이를 1시간 범위 내에서 연장할 수 있다.', related_words = ARRAY['소액지급시스템']::text[] WHERE id = 553;  -- 지방은행공동망
UPDATE public.words SET meaning = '지식서비스 무역통계는 국가 간의 지식 기반 서비스 거래 흐름을 계량적으로 측정하고 분석하기 위한 통계로서, 국제수지 통계의 서비스수지에 포함되어 있는 ① 지식재산권 사용료 ② 정보·통신서비스 ③', detailed_meaning = '지식서비스 무역통계는 국가 간의 지식 기반 서비스 거래 흐름을 계량적으로 측정하고 분석하기 위한 통계로서, 국제수지 통계의 서비스수지에 포함되어 있는 ① 지식재산권 사용료 ② 정보·통신서비스 ③ 문화·여가서비스 ④ 전문·사업서비스 등 4대 지식서비스 분야 를 세분화하여 제공한다. 동 통계는 이들 4대 분야를 16개 세부 유형으로 나누어 산업별 (표준산업분류), 기관형태별(대기업, 중기업, 소기업 등), 거래상대지역별(북미, 아시아, 유럽 등)로 세분화된 수출·수입 및 수지(수출 - 수입) 정보를 보여주며, 표준산업분류상별도 산업분류가 없는 ICT 산업과 콘텐츠 산업에 대해서도 통계를 제공한다.', related_words = ARRAY['국제수지']::text[] WHERE id = 555;  -- 지식서비스 무역통계
UPDATE public.words SET meaning = '지식재산권(Intellectual Property Rights)은 인간의 창의적 활동이나 지식 기반의 산출물에 대해 창작자나 발명가, 개발자 등에게 독점적 사용과 배타적 권리를 부여하는', detailed_meaning = '지식재산권(Intellectual Property Rights)은 인간의 창의적 활동이나 지식 기반의 산출물에 대해 창작자나 발명가, 개발자 등에게 독점적 사용과 배타적 권리를 부여하는 법적권리이다. 크게 산업재산권과 저작권으로 나뉘며, 산업재산권에는 특허권, 실용신안권, 디자인권, 상표권 등이 포함되고, 저작권은 문학·예술·음악·소프트웨어 등 창작물을 대상으로 한다. 최근에는 영업비밀, 반도체 배치설계, 생명공학적 발명, 데이터베이스 등도 지식재산권의 대상에 포함되고 있다. 과학 기술이 급속히 발달하고 사회에서의 소비 형태도 다양해지면서 새로운 형태의 지식재산권이 나타나고 있으며, 이에 세계 각국은 지식재산권의 보호를 강화하고 있다. 하지만 지식재산권에 대한 기준이 국가마다 일정하지 않고, 특히 개발도상국은 사실상 복제가 방치되고 있다는 점에서 지식재산권에 대한 국가 간 논란이 자주 발생하고 있다.', related_words = '{}'::text[] WHERE id = 556;  -- 지식재산권
UPDATE public.words SET meaning = '실시간 총액결제시스템에서 금융기관의 이체지시는 신청 즉시 처리되는 것이 원칙이나 어음교환, 타행환 등의 차액결제와 같이 거래 성격상 다수 금융기관 간에 일괄결제가 필요한 거래는 영업시간중', detailed_meaning = '실시간 총액결제시스템에서 금융기관의 이체지시는 신청 즉시 처리되는 것이 원칙이나 어음교환, 타행환 등의 차액결제와 같이 거래 성격상 다수 금융기관 간에 일괄결제가 필요한 거래는 영업시간중 특정시점에 처리하고 있는데 이를 지정시점처리제도라 한다. 자금의 이체지시를 영업시간 중에 건별로 실시간 처리하는 실시간총액결제방식에 대응하는 개념이다. 지정시점처리제도는 다수의 참가기관이 서로 연결되는 대량의 거래를 특정시점에서 일괄적으로 처리함으로써 참가기관들이 예측가능하고 효율적인 자금관리를 할수 있고 결제에 필요한 유동성을 절약할 수 있는 장점이 있는 반면 지정시점에 모든 참가 기관이 결제를 이행한다는 보장이 없어 별도의 결제리스크 관리방안이 구비되어야 한다. 현재 한은금융망에서는 11시(금융기관 간 차액결제가 이루어지는 타행환, CD공동망, 은 행지로, 직불카드, CMS, 지방은행공동망, 전자금융공동망, 어음교환 등), 11시 5분(1일물콜자금 상환), 14시(국고금 수납자금 회수) 등의 지정처리시점을 설정·운영하고 있다.', related_words = ARRAY['차액결제시스템']::text[] WHERE id = 558;  -- 지정시점처리제도
UPDATE public.words SET meaning = '직불카드(Debit Card)는 카드소지인(고객)이 물품이나 서비스를 구매하는 경우 동 카드를 이용하여 판매점에 설치되어 있는 단말기와 카드 발급은행의 주전산기를 통하여 고객의 예금계좌에서', detailed_meaning = '직불카드(Debit Card)는 카드소지인(고객)이 물품이나 서비스를 구매하는 경우 동 카드를 이용하여 판매점에 설치되어 있는 단말기와 카드 발급은행의 주전산기를 통하여 고객의 예금계좌에서 구매대금을 인출하고 이를 판매자의 예금계좌로 자동이체해 주는 용도 로 사용되는 카드이다. 직불카드는 백화점, 슈퍼마켓 등 판매점에서 물품판매와 동시에 고객의 계좌에서 대금이 출금되어 현금을 지급하는 것과 동일한 효과가 있으므로 EFT/ POS (Electronic Funds Transfer at the Point of Sales)카드라고도 부른다. 우리나라에 서는 1996년 2월부터 본격 가동되기 시작한 직불카드공동망을 통하여 서비스가 제공되고 있다.', related_words = ARRAY['지급수단','직불카드공동망']::text[] WHERE id = 560;  -- 직불카드
UPDATE public.words SET meaning = '직불카드공동망은 직불카드 소지자가 판매점에서 동 카드를 사용하여 상품·서비스를 구입하면 판매대금이 카드소지자 은행 계좌에서 인출되어 다음 영업일 판매자 은행 계좌로 입금되는 지급시스템으로', detailed_meaning = '직불카드공동망은 직불카드 소지자가 판매점에서 동 카드를 사용하여 상품·서비스를 구입하면 판매대금이 카드소지자 은행 계좌에서 인출되어 다음 영업일 판매자 은행 계좌로 입금되는 지급시스템으로 1996년 2월 가동되었다. 직불카드 소지자가 판매점에서 거래대금을 직불카드로 지급하면 거래내역이 VAN사업자의 네트워크를 경유하여 직불카드 발급은행으로 전송되고 발급은행은 즉시 고객계좌에서 거래대금을 출금하여 직불카드계정으로 이체한다. 그리고 거래 익일이 되면 금융결제원은 각 VAN사업자로부터직불카드 사용내역을 집계하여 은행별 차액을 계산한 후 한국은행에 전송함과 동시에 판매점 거래은행 앞으로 입금내역을 통보함으로써 거래대금이 판매점의 계좌에 입금되도록 하고 있다.', related_words = ARRAY['소액지급시스템','직불카드']::text[] WHERE id = 561;  -- 직불카드공동망
UPDATE public.words SET meaning = '직접투자는 한 나라의 기업이 국외 현지법인의 경영에 직접 참여하여 영업이익을 획득할목적으로 자사 보유 자본, 기술 및 인력 등의 생산요소를 국외로 이전하는 거래행위를 말한다.', detailed_meaning = '직접투자는 한 나라의 기업이 국외 현지법인의 경영에 직접 참여하여 영업이익을 획득할목적으로 자사 보유 자본, 기술 및 인력 등의 생산요소를 국외로 이전하는 거래행위를 말한다. 직접투자는 국외 현지법인과 지속적인 경제관계 수립 또는 경영권 획득을 목적으로 한다는 점에서 배당금, 이자나 자본이득(capital gain) 등을 목적으로 하는 간접투자 또는 증권투자(portfolio investment)와 구별된다. 직접투자는 자금흐름 및 투자주체에 따라 외국인(비거주자)의 국내직접투자(FDI; Foreign Direct Investment)와 내국인(거주자)의 해외직접투자(overseas direct investment)로 나눌 수 있다. 직접투자의 유형은 경영참가를 목적으로 하는 현지법인에 대한 지분매입, 장기 금전대여 등이 있으며 지분매입방법으로는 신규로 국외에 현지법인을 설립하는 공장설립형(greenfield) 투자와 기존 국외기업의 인수합병(M&A) 투자가 있다. 다만 장기 금전대여가 직접투자에 포함되려면 투자자가 실질적 경영권 또는 영향력을 행사할 수 있는 구조여야 한다.', related_words = '{}'::text[] WHERE id = 562;  -- 직접투자
UPDATE public.words SET meaning = '특정 산업에 속한 시장참여자들의 매출액이나 자산규모 등을 기준으로 시장점유율을 백분율(%)로 산출한 후 이들 모두를 각각 제곱한 값을 합산한 수치로, 이 수치가 높을수록해당 산업이 소수의', detailed_meaning = '특정 산업에 속한 시장참여자들의 매출액이나 자산규모 등을 기준으로 시장점유율을 백분율(%)로 산출한 후 이들 모두를 각각 제곱한 값을 합산한 수치로, 이 수치가 높을수록해당 산업이 소수의 참여자들에 의한 지배력이 커짐을 나타낸다. 미국에서는 특정 기업의 지배력이 과다하게 커지는 것을 예방하기 위해 1992년부터 반독점금지국(DOJ)과 연방거래위원회(FTC)를 통해 합병가이드라인을 운영하고 있다. DOJ와 FTC 두 기관은 기업들의 합병이 경쟁에 미치는 영향을 평가하기 위해 ‘합병 전 HHI’와 ‘합병 후 HHI’를 비교한다. HHI의 기준점을 1000으로 하여, 1000 이하이면 시장의 집중이 없다고 판단하지만 1000에서 1800 사이인 경우 시장이 다소 집중되었다고 본다. 그리고 합병 후에 1800 이상인 경우에는 합병 후 HHI 지수가 50 포인트 이상 늘어나면 합병을 금지하는 것이 타당하다고 보고, 100 포인트 이상 늘어나면 소수의 예외적인 경우를 제외하고는 합병을 금지하는 조치를 취하게 된다. HHI(Herfindahl-Hirschman Index)는 소수의 기업이 시장점유율을 분할하고 있는 경우일수록 그리고 특정 기업의 시장점유율이 높을수록 수치가 커지게 되므로 소수 기업들 간의 과점적 협조활동으로 인한 공정한 경쟁의 제한 가능성을 측정하는데 이용된다.', related_words = '{}'::text[] WHERE id = 565;  -- 집중도 지수(HHI)
UPDATE public.words SET meaning = '만기 시 당초 약정한 환율에 의해 특정 통화를 거래당사자 간에 인도 또는 인수하는 일반적인 선물환거래와 달리 만기에 계약원금의 교환 없이 약정환율과 만기 시 현물환율인 지정환율(fixing', detailed_meaning = '만기 시 당초 약정한 환율에 의해 특정 통화를 거래당사자 간에 인도 또는 인수하는 일반적인 선물환거래와 달리 만기에 계약원금의 교환 없이 약정환율과 만기 시 현물환율인 지정환율(fixing rate) 간의 차액만을 지정통화로 결제하는 거래를 말한다. 차액만 결제하기 때문에 일반 선물환거래보다 결제위험이 작으며 적은 금액으로 거래할 수 있으므로 레버리지(leverage) 효과가 높아 환리스크 헤지 수단은 물론 환차익을 획득하기 위한 투기적 거래에도 널리 이용되고 있다. 또한 NDF(Non Deliverable Forward)의 지정통화가 주로 미 달러화이므로 비거주자는 원화와 같이 국제화되지 않은 통화를 보유하거나 환전할 필요 없이 자유롭게 선물환거래를 할 수 있다는 장점이 있다. 지정환율은 당사자 간 약정에 따라 결정되며 통상 원-달러 NDF의 경우 만기일 전일의 매매기준율로 정한다. 만기는 일반적으로 1개월, 2개월, 3개월, 6개월, 9개월, 1년, 2년, 3년, 4년, 5년으로 되어 있다. 예를 들어 A은행이 3개월 후 1달러당 1,300원에 B은행으로부터 100만 달러를 사들이기로 하는 NDF 계약을 체결한 경우, 3개월 후 만기일 전일에 현물시장 환율(지정환율)이 1,400원/달러가 된다면 A은행은 달러당 100원씩 총 1억 원의 이득을 보게 된다. 그리고 B은행은 이 돈을 달러(즉 71,428.57달러)로 만기일에 A은행에게 지급한다. 한편 NDF 거래에는 시장 유동성 위험, 정보 비대칭, 거래 비용, 예상치 못한 손실등 단점도 존재한다. 또한 투기적 거래가 활성화될 경우 환율 변동성을 키울 수 있다는 점에도 유의할 필요가 있다.', related_words = ARRAY['선물환거래','환리스크 헤지']::text[] WHERE id = 566;  -- 차액결제선물환(NDF) 거래
UPDATE public.words SET meaning = '결제시스템에 참가하는 금융기관 간 자금결제에서 일정 기간(보통 1일) 동안 발생한 거래의 상호 지급액과 수취액을 모두 상계처리한 다음 그 차액만을 이체하여 결제하는 시스템으로 양자간', detailed_meaning = '결제시스템에 참가하는 금융기관 간 자금결제에서 일정 기간(보통 1일) 동안 발생한 거래의 상호 지급액과 수취액을 모두 상계처리한 다음 그 차액만을 이체하여 결제하는 시스템으로 양자간 차액결제시스템과 어음교환, CD, 타행환시스템 등과 같이 다수의 금융기관간에 이루어지는 다자간 차액결제시스템으로 구분된다. 차액결제시스템은 참가기관간 자금거래를 매 건별로 결제하는 총액결제에 비해 결제 건수 및 금액을 대폭 축소함으로써참가기관의 자금부담을 경감시키고 결제시스템의 효율성을 높이기 때문에 지급건수가 많고 금액이 작은 소액결제시스템에 매우 적합한 제도라 할 수 있다. 그러나 차액결제시스템에서는 거래일 영업마감 후 또는 그 다음 영업일에 참가기관간 거래차액이 중앙은행의 당좌예금 계좌를 통해 최종적으로 결제될 때까지 참가기관의 결제불이행 위험에 노출되어 있어 보다 엄격한 리스크 관리방식이 요구된다.', related_words = ARRAY['소액지급시스템','지정시점처리제도']::text[] WHERE id = 567;  -- 차액결제시스템
UPDATE public.words SET meaning = '차입매수(LBO; Leveraged Buy out)란 기업을 매수하려는 주체가 인수에 필요한 자금이 충분하지 않은 경우 금융기관 등으로부터 인수대상 기업의 자산을 담보로 인수자금을 차입하여 기업을', detailed_meaning = '차입매수(LBO; Leveraged Buy out)란 기업을 매수하려는 주체가 인수에 필요한 자금이 충분하지 않은 경우 금융기관 등으로부터 인수대상 기업의 자산을 담보로 인수자금을 차입하여 기업을 매수하는 방식을 말한다. 인수 및 합병이 이루어진 후에는 인수한 기업의 자산을 매각하거나 또는 직접 인수한 기업을 경영하여 발생한 수익으로 차입금을 상환하게 된다. 차입매수는 자기자본 부담 없이도 기업을 매수할 수 있는 것이 가장 큰 장점이 다. 그러나 기업 인수후 차입금을 상환하지 못할 신용위험이 커지며, 기업 매수 완료 후자기자본비율이 하락하는 등 재무건전성이 취약해질 가능성도 있고, 자산을 매각하는 과 정에서 대대적인 구조조정도 수반되는 등 많은 약점도 가지고 있다. 그래서 이 제도는 주로 투기펀드들의 고수익 투자방안으로 많이 활용되고 있다.', related_words = '{}'::text[] WHERE id = 568;  -- 차입매수(LBO)
UPDATE public.words SET meaning = '채권시가평가(Mark to Market)란 금융기관들이 보유하고 있는 채권에 대한 가치를 적절한 가격(시장에서 거래가 활발한 채권은 시장가격으로, 거래부진으로 시장가격을 발견하기 곤란한 경우에는', detailed_meaning = '채권시가평가(Mark to Market)란 금융기관들이 보유하고 있는 채권에 대한 가치를 적절한 가격(시장에서 거래가 활발한 채권은 시장가격으로, 거래부진으로 시장가격을 발견하기 곤란한 경우에는 보유채권을 시장에 매각할 경우 받을 수 있을 것으로 합리적으로 추정되는 공정가격)으로 평가하는 것을 의미하며 2000년 7월부터 전면 시행되었다. 평가대상은 금융기관이 보유한 채권과 자산운용사 등 집합투자업자의 간접투자상품이다. 금융기관이 보유한 채권은 단기매매계정, 매도가능계정, 만기보유계정 등으로 분류하는데 단기매매계정에서의 시가평가 손익은 당기손익에 반영되고, 매도가능계정의 경우 시가평가대상이나 당기손익에 반영하지 않고 재무상태표상 기타포괄손익누계액(자본을 구성하는 항목)으로 처리하고, 만기보유계정은 장부가평가를 원칙으로 하고 있다. 매도가능계정으로 분류된 채권의 경우 처분으로 손익이 실현되었을 때는 그 손익이 비로소 당기손익에 반영된다. 채권을 시가로 평가하는 이유는 시가와 장부가 사이의 지나친 괴리로 채권가격이 과도하게 저평가 또는 고평가될 경우 발생할 수 있는 재무지표의 왜곡(당기손익의 과 소 또는 과대계상 등)을 방지하는데 그 목적이 있다. 특히 집합투자자산으로 편입된 채권에 시가평가를 하지 않는다면 동 채권에 신용위험이 발생한 경우 나중에 환매한 투자자에 게 그 손실이 대부분 전가될 수 있기 때문에 손실의 공정한 배분을 위해서도 채권시가평가제도는 필요하다. 한편, 법인형 MMF의 경우 2022년 4월부터 시가평가제도가 도입되었으며, 일정 조건(안정적 자산 비중)이 충족되는 경우에는 예외적으로 장부가 평가를 허용하고 있다.', related_words = '{}'::text[] WHERE id = 569;  -- 채권시가평가
UPDATE public.words SET meaning = '채권시장안정펀드란 2008년 9월 미국발 금융위기로 국내 금융시장이 경색됨에 따라 국내 금융기관이나 기업이 채권이나 기업어음 발행을 통해 원활하게 자금을 조달할 수 있도 록 2008년 11월에', detailed_meaning = '채권시장안정펀드란 2008년 9월 미국발 금융위기로 국내 금융시장이 경색됨에 따라 국내 금융기관이나 기업이 채권이나 기업어음 발행을 통해 원활하게 자금을 조달할 수 있도 록 2008년 11월에 만들어진 펀드이다. 동 펀드에는 국내은행, 증권사, 보험사들이 출자하여 5조원의 펀드를 조성하였다. 이렇게 조성된 자금은 당시 잠재적으로 금융시스템 불안을 야기할 수 있는 취약부문이 발행하는 채권(중소기업 P-CBO, 건설사 ABCP 및 일부대기업의 회사채)을 우선적으로 매입함으로써 취약부문에 자금을 선제적으로 공급하였고 은행 및 카드사의 원활한 자금 조달을 돕기 위해 은행채나 카드채도 일부 매입하였다. 특히 동 펀드에 대한 자금 출자로 금융기관의 유동성 부족이 우려됨에 따라 한국은행은 동펀드에 출자한 금융기관에 대해 출자금액의 50%까지 자금을 지원하였다. 당시 신용 경색으로 자본시장을 통한 자금조달이 매우 어려운 상황에서 동 펀드는 직접금융시장의 자금흐름을 개선하고 취약부문의 자금난을 완화하는 데 크게 기여한 것으로 평가되고 있다. 이후 코로나19 팬데믹으로 국내 금융시장이 불안해지자 2020년 4월 20조원 규모의 채권시장안정펀드가 재가동되었고, 2022년 10월에는 레고랜드 사태로 인한 단기자금시장 불안에 대응하여 재가동되기도 하였다.', related_words = '{}'::text[] WHERE id = 571;  -- 채권시장안정펀드
UPDATE public.words SET meaning = '채무불이행(Default)은 채무자가 계약상 또는 법률상 부담하는 채무를 그 내용대로 이행하지 않거나, 이행할 수 없는 객관적인 상태에 빠지는 것을 의미한다.', detailed_meaning = '채무불이행(Default)은 채무자가 계약상 또는 법률상 부담하는 채무를 그 내용대로 이행하지 않거나, 이행할 수 없는 객관적인 상태에 빠지는 것을 의미한다. 이는 법률 분야에서 흔히 사용되는 개념이지만, 특히 금융 및 경제 영역에서도 빈번히 사용된다. 채무불이행은 크게 이행지체, 이행불능, 불완전이행의 세 가지 유형으로 분류될 수 있다. 이행지체는 채무의 이행기가 도래하였음에도 불구하고 채무자가 정당한 이유 없이 채무를 이행하지않는 경우를 말한다. 이행불능은 채무의 이행이 채무자의 귀책사유로 인해 사회통념상 불가능하게 된 경우를 의미한다. 불완전이행은 채무의 이행은 이루어졌으나, 그 이행이 채무의 내용에 완전히 부합하지 못한 경우를 말한다. 채무불이행이 발생하면 채권자는 채무자에 대해 손해배상을 청구할 수 있으며, 계약의 해제, 담보권 실행 등 다양한 법적 조치를 취할 수 있다. 금융부문에서 채무불이행은 개인의 신용등급 하락, 금융기관의 부실채권 증가, 나아가 금융시스템 전반의 불안정성을 초래할 수 있다. 또한 거시경제적으로는 기업의 연쇄 도산, 실업률 증가, 소비 위축 등 경기 침체로 이어질 수 있으므로 채무불이 행 위험 관리는 개인, 기업, 금융기관 및 정부 등 모든 경제주체에 중요한 과제이다.', related_words = '{}'::text[] WHERE id = 572;  -- 채무불이행
UPDATE public.words SET meaning = '자금지급 거래에서 청산(Clearing)은 경제주체간 지급행위가 수표, 계좌이체 등 비현금수단을 이용하여 이루어진 경우 지급인과 수취인의 거래은행들이 주고 받을 금액을 정산하고 최종 확정하는', detailed_meaning = '자금지급 거래에서 청산(Clearing)은 경제주체간 지급행위가 수표, 계좌이체 등 비현금수단을 이용하여 이루어진 경우 지급인과 수취인의 거래은행들이 주고 받을 금액을 정산하고 최종 확정하는 과정을 말한다. 거래 이후 지급수단의 수령, 전달, 조회, 통지 및 차액계산(netting)이나 결제전 포지션 산출과정 모두가 청산에 포함된다. 증권결제의 경우에서 도 증권시장에서 거래된 증권의 매매사실을 확인하고 차감을 거쳐 최종 결제자료를 산출하는 과정을 청산이라 한다. 우리나라의 경우 인터넷뱅킹, 어음 및 수표 등 소액거래에서 는 금융결제원, 장내유가증권시장에서는 한국거래소, 장외채권시장에서는 한국예탁결제원이 청산기관 역할을 한다.', related_words = ARRAY['지급','결제']::text[] WHERE id = 574;  -- 청산
UPDATE public.words SET meaning = '청산소(Clearing House)는 금융시장에서 은행, 증권사 등 거래당사자들 사이에 발생하는 다수의 지급 거래를 집중적으로 처리하여, 각 거래의 채권·채무를 확정하고 최종결제를 위한 포지션을', detailed_meaning = '청산소(Clearing House)는 금융시장에서 은행, 증권사 등 거래당사자들 사이에 발생하는 다수의 지급 거래를 집중적으로 처리하여, 각 거래의 채권·채무를 확정하고 최종결제를 위한 포지션을 산정하는 핵심 금융인프라이다. 청산(clearing)은 결제를 위해 송부된 어음, 수표, 계좌이체 등의 지급수단을 확인한 후 최종적으로 수취하거나 해당 금융기관간에 지급해야 할 금액을 산출하는 과정과 거래 이후 지급수단의 수령, 전달, 조회, 통지및 차액계산(netting)이나 결제 전의 포지션 산출과정 모두를 포함하는 개념이다. 청산소는 청산 과정을 통한 결제(settlement)를 위한 기초자료를 산출하며, 이 과정에서 거래당사자 간의 채권·채무 관계가 명확히 정리되어 결제의 효율성과 안정성이 크게 향상된다.', related_words = ARRAY['결제','청산']::text[] WHERE id = 575;  -- 청산소
UPDATE public.words SET meaning = '기업에서는 지속적인 생산능력을 유지하고 경쟁력을 확보하기 위해 노후설비를 새로운설비로 대체하거나 신규 사업 진출을 위해 공장도 짓고 기계도 구매하는데 이러한 경제활동은 해당연도의 이익만을 위한', detailed_meaning = '기업에서는 지속적인 생산능력을 유지하고 경쟁력을 확보하기 위해 노후설비를 새로운설비로 대체하거나 신규 사업 진출을 위해 공장도 짓고 기계도 구매하는데 이러한 경제활동은 해당연도의 이익만을 위한 것이 아니고 미래의 지속적인 수입의 보장 등 장기적인안목에서 이루어진다. 이렇게 장기간에 걸쳐 생산과정에 반복적, 지속적으로 사용되는 유형 또는 무형의 산출물을 고정자산이라 하고, 생산주체에 의한 고정자산의 순취득(취득- 처분)을 총고정자본형성(GFCF; gross fixed capital formation)이라 한다. 총고정자본형성에는 토지나 중고품의 구매는 제외되고 고정자산 취득에 따른 설치비용이나 취득세, 등록세 등의 부대비용은 포함된다. ㅊ', related_words = ARRAY['총투자율']::text[] WHERE id = 576;  -- 총고정자본형성
UPDATE public.words SET meaning = '차주의 연간 소득 대비 연간 대출 원리금 상환액의 비율(Debt-To-Income ratio)을 의 미한다.', detailed_meaning = '차주의 연간 소득 대비 연간 대출 원리금 상환액의 비율(Debt-To-Income ratio)을 의 미한다. 주택담보대출 차주의 원리금상환능력을 감안하여 주택담보대출 한도를 설정하기 위해 도입된 규제 비율이다. 「은행업감독업무시행세칙」에서는 “총부채상환비율 = [(해당 주택담보대출 및 기존 주택담보대출의 연간 원리금 상환액 + 기타부채의 연간이자상환액) / 연소득] × 100” 방식으로 산정하도록 하고 있다. DTI 규제는 담보인정비율(LTV) 규제 강화의 후속조치로 2005년 8월 도입되었으며, 이는 차주의 상환능력과 관계없이 담보가치(주택가격)에 비례하여 주택담보대출 한도가 결정되는 LTV 규제의 문제점을 보완하고자 도입한 것이다. 특히 과도한 가계부채의 증가 억제 및 주택자금 수요 축소 등을 위해 DTI 비율을 특정수준 이내로 제한하기도 한다. 한편, DTI 규제는 LTV 규제와 함 께 대표적인 특정 부문에 대한 거시건전성정책 수단으로서 통화신용정책과 상호 보완적인 관계를 가지고 있다. 예를 들어 저금리 하에서 주택가격 상승세가 확대될 경우 DTI 및LTV 규제를 강화하면 주택담보대출 한도가 축소되어 주택시장 과열을 억제하는 효과를 기대할 수 있다.', related_words = ARRAY['담보인정비율(LTV)','총부채원리금상환비율(DSR)']::text[] WHERE id = 577;  -- 총부채상환비율(DTI)
UPDATE public.words SET meaning = '총저축은 국민총처분가능소득에서 소비하고 남은 부분이다.', detailed_meaning = '총저축은 국민총처분가능소득에서 소비하고 남은 부분이다. 총저축은 투자재원으로 차기생산을 증가시키는데 이용되거나 대외자산구입에 이용되므로 이론적으로는 국내총투자에 국외투자를 더한 총투자와 일치한다. 총저축 = 국민총처분가능소득 - 소비총저축률은 100에서 국민총처분가능소득 중 최종소비를 목적으로 처분된 재화와 서비스의 비율인 소비율을 차감한 것이다. 이때 소비율을 백분율이 아닌 계수로 표시한 것을 평균소비성향이라 하며, 평균저축성향은 1에서 평균소비성향을 차감한 것이다. 총저축률 = 100 - 소비율* * 최종소비지출/국민총처분가능소득** × 100 ** ‌피용자보수 + 영업이익(국외순수취영업이익 및 재산소득 포함) + 순생산 및 수입세 +국외순수취경상이전 + 고정자본소모)평균소비성향 = 최종소비지출/국민총처분가능소득평균저축성향 = 1 - 평균소비성향', related_words = ARRAY['국민총처분가능소득','국민계정체계(SNA)']::text[] WHERE id = 582;  -- 총저축/총저축률/평균소비성향/ 평균저축성향
UPDATE public.words SET meaning = '국가가 노사 간의 임금결정 과정에 개입하여 임금의 최저수준을 정하고 그 이상 임금을 지급하도록 강제함으로써 근로자를 보호하는 제도이다.', detailed_meaning = '국가가 노사 간의 임금결정 과정에 개입하여 임금의 최저수준을 정하고 그 이상 임금을 지급하도록 강제함으로써 근로자를 보호하는 제도이다. 최저임금제도는 1894년 뉴질랜드가 가장 먼저 도입하였으며 우리나라는 1986년 12월 31일 최저임금법을 제정·공포하고 1988년 1월 1일부터 이를 시행하였다. 최저임금제를 도입하는 목적은 임금의 최저수준을 보장하여 근로자의 생활안정과 노동력의 질적 향상에 이바지하고, 임금격차를 완화하여 소득분배 개선에 기여하며, 근로자의 생활안정 및 근로자의 사기진작을 통해 노동생산성을 향상시키고, 적정임금을 지급하여 공정경쟁을 촉진하는 등으로 다양하다. 현행 최저임금법 및 동법시행령에 따르면 고용노동부장관은 매년 8월 5일까지 다음 연도중 적용할 최저임금을 결정하여 고시해야 하며 최저임금액 보다 적은 금액의 임금을 지급하는 경우에는 3년 이하의 징역 또는 2천만원 이하의 벌금이 부과된다.', related_words = ARRAY['의중임금']::text[] WHERE id = 583;  -- 최저임금제
UPDATE public.words SET meaning = '최종대부자(Lender of Last Resort) 기능은 금융시장 불안 등으로 일시적인 지급불능 상태에 빠진 금융기관에 대하여 중앙은행이 발권력을 동원하여 부족자금을 신속하게 대출해주는 기능을', detailed_meaning = '최종대부자(Lender of Last Resort) 기능은 금융시장 불안 등으로 일시적인 지급불능 상태에 빠진 금융기관에 대하여 중앙은행이 발권력을 동원하여 부족자금을 신속하게 대출해주는 기능을 말한다. 즉, 개별 은행에 대해 예금인출요구가 일시에 몰릴 경우 지급능력의 유무와 관계없이 유동성 부족상태에 직면하게 되고 이는 해당 은행의 파산, 나아가 은 행의 연쇄 도산 등으로 이어져 국민경제적으로 부정적인 파급효과를 가져오게 되므로, 중앙은행이 시중에 충분한 자금을 공급함으로써 사람들의 심리를 안정시키고 위기의 확산을 방지하여 전체 금융시장의 안정을 도모하는 것이다. 다만 이러한 기능 수행 시에는 금융기관의 과다차입 및 도덕적 해이를 방지하기 위해 시장금리보다 다소 높은 수준의 대출금리가 적용된다. 이와 같은 기능은 중앙은행이 독점적인 발권력을 가진 데 따른 것으로 써 중앙은행의 중요한 고유기능의 하나이다. 한편 최종대부자 기능의 개념은 글로벌 금융위기 극복 과정에서 그 범위가 확대되었는데, 중앙은행은 금융안정 회복을 위해 개별 금융기관뿐만 아니라 금융시장에 대해서도 적극적으로 유동성을 공급하였고, 이를 전통적인 최종대부자 기능과 구분하여 최종시장조성자(market maker of last resort) 기능이라고 부르기도 한다.', related_words = '{}'::text[] WHERE id = 584;  -- 최종대부자 기능
UPDATE public.words SET meaning = '추가경정예산이란 행정부가 예산을 성립한 후에 발생한 사회·경제적인 변동으로 인해 기존의 예산을 추가·삭감하여 바꾼 예산을 가리킨다.', detailed_meaning = '추가경정예산이란 행정부가 예산을 성립한 후에 발생한 사회·경제적인 변동으로 인해 기존의 예산을 추가·삭감하여 바꾼 예산을 가리킨다. 즉 헌법에서는 예산안을 편성할 때 예산 성립 후 예상치 못한 지출에 대비하기 위해 따로 예비비를 두고 있으나, 이것만으로 충당할 수 없을 때에는 추가적으로 세출을 조정하는 등을 통해 추가경정예산을 짤 수 있다. 본예산에 대비되는 용어이며 보정예산이라고도 한다. 구재정법에서는 추가예산과 경정예산으로 구분하여 규정한 바 있으나 헌법(헌법 제56조)과 국가재정법(제89조)에서는 이를 통합하여 추가경정예산이라 부른다. 이는 행정부가 예산안을 국회에 제출한 후 예산이 성립되기 전에 불가피한 사유로 예산안의 일부를 수정하는 수정예산과는 구별된다.', related_words = ARRAY['재정정책']::text[] WHERE id = 586;  -- 추가경정예산
UPDATE public.words SET meaning = '출금이체(Debit Transfer)는 수취인이 자신이 거래하는 금융기관에 추심을 의뢰하여(즉, 인출지시) 지급인의 계좌로부터 이체금액을 출금하여 수취인 자신의 계좌에 입금하도록하는 계좌이체방식을', detailed_meaning = '출금이체(Debit Transfer)는 수취인이 자신이 거래하는 금융기관에 추심을 의뢰하여(즉, 인출지시) 지급인의 계좌로부터 이체금액을 출금하여 수취인 자신의 계좌에 입금하도록하는 계좌이체방식을 말한다. 대표적인 출금이체방식으로는 수표 추심, 지로시스템의 자동이체, 자금관리서비스(CMS)공동망의 대량자금이체 중 출금이체가 있다. 지로의 자동이체와 CMS의 출금이체는 모두 사전 약정된 수취인의 자금인출지시로 납부자의 예금계좌에서 자금이 인출되어 수납자의 예금계좌로 자동이체된다.', related_words = ARRAY['자금관리서비스(CMS)공동망','추심','입금이체']::text[] WHERE id = 588;  -- 출금이체
